(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["448"] = {"atoms": {"448.1": {"x": [[45, "إلجام العوام عن علم الكلام\rخطبة المؤلف\r"]], "pg": [45, 45]}, "448.2": {"x": [[45, "بسم اللّه الرّحمن الرّحيم\rالحمد للّه الذي تجلى لكافة عباده بصفاته وأسمائه وتاهت عقول الطالبين في بيداء كبريائه، وقص أجنحة الأفكار دون حمى عزته وتعالى بجلاله عن أن تدرك الأفهام كنه حقيقته.\rو استوفى قلوب أوليائه وخاصته واستغرق أرواحهم حتى احترقوا بنار محبته وبهتوا في إشراق أنوار عظمته، وخرست ألسنتهم عن الثناء على جمال حضرته إلا بما أسمعهم من أسمائه وصفاته وأنبأهم على لسان رسوله محمد صلى اللّه عليه وسلم خير خليقته وعلى أصحابه وعترته.\rأما بعد: فقد سألتني أرشدك اللّه عن الأخبار الموهمة للتشبيه عند الرعاع والجهال من الحشوية الضلال حيث اعتقدوا في اللّه وصفاته ما يتعالى ويتقدس عنه من الصورة واليد والقدم والنزول والانتقال والجلوس على العرش والاستقرار، وما يجري مجراه مما أخذوه من ظواهر الأخبار وصورها، وأنهم زعموا أن معتقدهم فيه معتقد السلف."], [46, "وأردت أن أشرح لك اعتقاد السلف، وأن أبين ما يجب على عموم الخلق أن يعتقدوه في هذه الأخبار، وأكشف فيه الغطاء عن الحق، وأميز ما يجب البحث عنه عما يجب الإمساك والكف عن الخوض فيه، فأجبتك إلى طلبتك متقربا إلى اللّه سبحانه وتعالى بإظهار الحق الصريح من غير مداهنة ومراقبة جانب ومحافظة على تعصب لمذهب دون مذهب، فالحق أولى بالمراقبة، والصدق والإنصاف أولى بالمحافظة عليه، وأسأل اللّه التسديد والتوفيق وهو بإجابة داعيه حقيق، وها أنا أرتب الكتاب على ثلاثة أبواب:\rباب في بيان حقيقة مذهب السلف في هذه الأخبار.\rوباب في البرهان على الحق فيه مذهب السلف وأن من خالفهم فهو مبتدع.\rوباب في فصول متفرقة نافعة في هذا الفن."], [49, "الباب الأول: في شرح اعتقاد السلف في هذه الأخبار.\r"]], "pg": [45, 49]}, "448.3": {"x": [[49, "اعلم: أن الحق الصريح الذي لا مراء فيه عند أهل البصائر هو مذهب السلف أعني مذهب الصحابة والتابعين وها أنا أورد بيانه وبيان برهانه.\rفأقول: حقيقة مذهب السلف وهو الحق عندنا أن كل من بلغه حديث من هذه الأحاديث من عوام الخلق يجب عليه فيه سبعة أمور: التقديس، ثم التصديق، ثم اعتراف بالعجز، ثم السكوت، ثم الإمساك، ثم الكف، ثم التسليم لأهل المعرفة.\rأما التقديس: فأعني به تنزيه الرب تعالى عن الجسمية وتوابعها.\rوأما التصديق: فهو الإيمان بما قاله صلى اللّه عليه وسلم وإن ما ذكره حق وهو فيما قاله صادق وأنه حق على الوجه الذي قاله وأراده."], [50, "وأما الاعتراف بالعجز: فهو أن يقر بأن معرفة مراده ليست على قدر طاقته وأن ذلك ليس من شأنه وحرفته.\rوأما السكوت: فأن لا يسأل عن معناه ولا يخوض فيه ويعلم أن سؤاله عنه بدعة، وأنه في خوضه فيه مخاطر بدينه، وأنه يوشك أن يكفر لو خاض فيه من حيث لا يشعر.\rوأما الإمساك: فأن لا يتصرف في تلك الألفاظ بالتصريف والتبديل بلغة أخرى والزيادة فيه والنقصان منه والجمع والتفريق بل لا ينطق إلا بذلك اللفظ وعلى ذلك الوجه من الإيراد والإعراب والتصريف والصيغة.\rوأما الكف: فأن يكف باطنه عن البحث عنه والتفكر فيه.\rوأما التسليم لأهله: فأن لا يعتقد أن ذلك إن خفي عليه لعجزه فقد خفي على رسول اللّه صلى اللّه عليه وسلم أو على الأنبياء أو على الصديقين والأولياء، فهذه سبع وظائف اعتقد كافة السلف وجوبها على كل العوام لا ينبغي أن يظن بالسلف الخلاف في شيء منها، فلنشرحها وظيفة وظيفة."], [51, "الوظيفة الأولى: التقديس\r"]], "pg": [49, 51]}, "448.4": {"x": [[51, "ومعناه أنه إذا سمع (اليد والإصبع) وقوله صلى اللّه عليه وسلم \"إنّ اللّه خمّر طينة آدم بيده أربعين صباحا 1. وإنّ قلب المؤمن بين إصبعين من أصابع الرّحمن\"، فينبغي أن يعلم أن اليد تطلق لمعنيين أحدهما هو الموضع الأصلي وهو عضو مركب من لحم وعصب، واللحم والعظم والعصب جسم مخصوص وصفات مخصوصة أعني بالجسم عبارة عن مقدار له طول وعرض وعمق يمنع غيره من أن يوجد بحيث هو إلا بأن يتنحى عن ذلك المكان.\r(وقد يستعار هذا اللفظ) أعني اليد لمعنى آخر ليس ذلك المعنى بجسم أصلا كما يقال: البلدة في يد الأمير فإن ذلك مفهوم وإن كان الأمير مقطوع اليد مثلا.\r_________________\r1) أخرجه الآجري في «الشريعة، (31)، والبيهقي في «الأسماء والصفات، (ص 414) موقوفا على ابن مسعود أو سلمان الفارسي رضي الله عنهما، وانظر «إتحاف السادة المتقين» (502/ 9)، ومشکل الحديث، لابن فورك (ص 102 - 108).\r(2) رواه مسلم (2654) من حديث سيدنا عبد الله بن عمرو رضي الله عنهما."], [52, "فعلى العامي وغير العامي أن يتحقق قطعا ويقينا أنّ رسول اللّه صلى اللّه عليه وسلم لم يرد بذلك جسما هو عضو مركب من لحم ودم وعظم، وأن ذلك في حق اللّه تعالى محال وهو عنه مقدس.\rفإن خطر بباله أن اللّه جسم مركب من أعضاء ... فهو عابد صنم فإن كل جسم فهو مخلوق، وعبادة المخلوق كفر، وعبادة الصنم إنما كانت كفرا لأنه مخلوق، إنما كان مخلوقا لأنه جسم؛ فمن عبد جسما ... فهو كافر بإجماع الأمة؛ السلف منهم والخلف^1.\rسواء كان ذلك الجسم كثيفا كالجبال الصم الصلاب، أو لطيفا كالهواء والماء، وسواء كان مظلما كالأرض أو مشرقا كالشمس والقمر والكواكب, أو مُشِفّاً لا لون له كالهواء، أو عظيما كالعرش والكرسي، أو صغيرا كالذرة والهباء، أو جمادا كالحجارة، أو حيوانا كالإنسان؛ فالجسم صنم, بأن يقدّر حسنة وجماله أو عظمه أو صغره أو صلابته ونقاؤه .. لا يخرج عن كونه جسما 2.\rومن نفى الجسمية عنه وعن يده وإصبعه ... فقد نفى العضوية واللحم والعصب, وقدس الرب سبحانه عما يوجب الحدوث.\r_____________\r(1) وعلى هذا المعنى تحديدا يحمل عموم نصوص المذاهب الفقهية الأربعة الناطقة بتكفير المجسمة، لا على عموم المشبهة.\r(2) في (أ، د، و): (صنم) بدل (جسما)."], [53, "وليعتقد بعده أنه عبارة عن معنى من المعاني؛ ليس بجسم ولا عرض في جسم, يليق ذلك المعنى صفات الجلال والكبرياء.\rفإن كان لا يدري ذلك المعنى ولا يفهم كنه حقيقته, فليس عليه في ذلك تكليف أصلا، فمعرفة تأويله ومعناه ليس بواجب عليه بل واجب عليه أن لا يخوض فيه كما سيأتي 1.\rمثال آخر:\rإذا سمع (الصورة) من قوله صلى اللّه عليه وسلم: \"إنّ اللّه خلق آدم على صورته\" 2، \"وإنّي رأيت ربّي في أحسن صورة\" 3 فينبغي\rأن يعلم أن (الصورة) اسم مشترك؛ قد يطلق ويراد به الهيئة الحاصلة في أجسام مؤلّفة مرتبة ترتيبا مخصوصا؛ مثل الأنف والعين والفم والخدِّ التي هي أجسام وهي لحوم وعظام.\rوقد يطلق ويراد به ما ليس بجسم, ولا هيئة في جسم, ولا هو ترتيب في أجسام؛ كقولك عرفت صورة هذه المسألة, وصورة هذه الواقعة، وأنّ وزارة فلان وولايته منتظمة في أحسن صورة, وما يجري مجراه.\r_____________\r(1) انظر (ص 61).\r(2) رواه مسلم (2612) عن سيدنا أبي هريرة رضي الله عنه.\r(3) رواه الدارمي (2195) بلفظه هنا عن سيدنا عبد الرحمن بن عائش رضي الله عنه، وهو عند الترمذي (3233) وأحمد (368/\r1) بلفظ مقارب عن سيدنا عبد الله بن عباس رضي الله عنهما."], [54, "فليتحقق كل مؤمن: أن الصورة في حق اللّه لم تطلق لإرادة المعنى الأول؛ الذي هو جسم لحمي وعظمي, مركب من أنف وفم وخد وعين؛ فإن جميع ذلك أجسام وهيئات في أجسام، وخالق الأجسام والهيئات كلها منزه عن مشابهتها وصفاتها.\rفإذا عَلِمَ هذا يقينا ... فهو مؤمن, فإن خطر له أنّه إن لم يرد هذا المعنى ... فما الذي أراده؟\rفينبغي أن يعلم أن ذلك لم يؤمر به, بل أمر بأن لا يخوض فيه؛\rفإنه ليس على قدر طاقته، لكن ينبغي أن يعتقد أنه أريد به معنى يليق بجلال اللّه تعالى وعظمته؛ مما ليس بجسم ولا عرض في جسم.\rمثال آخر:\rإذا قرع سمعه النزول في قوله صلى اللّه عليه وسلم: \"ينزل اللّه تعالى في كلّ ليلة إلى السّماء الدّنيا\" 1.\rفالواجب عليه أن يعلم أن النزول اسم مشترك؛ قد يطلق إطلاقا يفتقر فيه إلى ثلاثة أجسام: جسم عال هو مكان لساكنه،\rوجسم سافل، وجسم منتقل من العالي إلى السافل.\rفهو اذا عبارة عن انتقال جسم من علو الى سفل؛ فإن كان من سفل الى عُلْوٍ ... سمّي صعوداً وعروجاً ورقيّاً, وإن كان من علو\r_________________\r1) رواه مسلم (758) عن سيدنا أبي هريرة رضي الله عنه"], [55, "إلى سفل سمي نزولا وهبوطا وحدوراً ... والى غير ذلك.\rوقد يطلق على معنى آخر ولا يفتقر فيه إلى تقدير انتقال وحركة في جسم، كما قال اللّه تعالى: وأَنْزَلَ لَكُمْ مِنَ الْأَنْعامِ ثَمانِيَةَ أَزْواجٍ [الزمر: 6]، وما رئي البعير والبقر نازلا من السماء بالانتقال، بل هي مخلوقة في الأرحام، ولإنزالها معنىً لا محالة، كما قال الشافعي رحمه اللّه: (دخلت مصر فلم يفهموا كلامي، فنزلت ثم نزلت ثم نزلت) , لم يرد به انتقال جسده إلى سفل.\rفايتحقق المؤمن: أن النزول في حق اللّه تعالى ليس بالمعنى الأول؛ وهو انتقال شخص وجسد من علو إلى سفل، فإن الشخص والجسد للأجسام. والرب تعالى ليس بجسم.\rفإن خطر له أنه لم يرد هذا ... فما الذي أراده؟\rفيقال له: أنت إذا عجزت عن فهم نزول البعير من السماء ... فأنت عن فهم نزول اللّه تعالى أعجز، فليس هذا بعُشِّكَ فادرج،\rواشتغل بعبادتك, أو حرفتك, واسكت، واعلم أنه أريد به معنى من المعاني, الذي يجوز أن يراد بالنزول في لغة العرب 1,\rويليق ذلك المعنى بجلال اللّه عز وجل وعظمته, وإن كنت لا تعلم حقيقته وكيفيته 2.\r____________________\r1) هذا نص هام في كتاب (الإلجام) فيه تصريح المصنف بجواز تأويل هذه الألفاظ حسب قانون اللغة.\r2) في (ب): (حقيقته وتعيُّنَهُ) , وفي (ه): (حقيقته ويقينه)."], [56, "ومثال آخر: إذا سمع لفظ الفوق في قوله تعالى: (وهُوَ الْقاهِرُ فَوْقَ عِبادِه) ِ [الأنعام: 18].\rوفي قوله تعالى: (يَخافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ) [النحل: 50]. فليعلم أن (الفوق) اسم مشترك يطلق لمعنيين:\rأحدهما: نسبة جسم إلى جسم؛ بأن يكون أحدهما أعلى والآخر أسفل؛ يعني أن الأعلى من جانب رأس الأسفل.\rوقد يطلق لا لهذا المعنى, فيقال: الخليفة فوق السلطان, والسلطان فوق الوزير، وكما يقال: دخل فلان على الأمير, وجلس فوق فلان، وكما يقال: العلم فوق العمل، والصياغة فوق الدباغة.\rوالأول: يستدعي جسما حتى ينسب إلى جسم, والثاني: لا يستدعيه.\rفليعتقد المؤمن قطعا: أن الأول غير مراد, وأنه على اللّه تعالى محال، فإنه من لوازم الأجسام أو لوازم أعراض الأجسام.\rوإذا عرف نفى هذا المحال عن القديم سبحانه ... فلا عليه إن لم يعرف أنه لماذا أطلق, وما ذا أريد به؛ فقد خفف الله عنه هذه الكلفة.\rوأمثلة هذا كثيرة, فقس على ما ذكرناه ما لم نذكره."], [57, "الوظيفة الثانية: الإيمان والتصديق\r"]], "pg": [51, 57]}, "448.5": {"x": [[57, "وهو أنه يعلم قطعا: أن هذه الألفاظ أريد بها معنى يليق بجلال اللّه تعالى وعظمته، وأن رسول اللّه صلى اللّه عليه وسلم\rصادق في وصف اللّه تعالى بها، فليؤمن بذلك, وليوقن بأن ما قاله صدق, وما أخبر عنه حق لا ريب فيه,\rوليقل آمنا وصدقنا، وأن ما وصف اللّه تعالى به نفسه أو وصفه به رسوله ... فهو كما وصفه,\rوحق بالمعنى الذي أراده, وعلى الوجه الذي قاله، وإن كنت لا أقف على حقيقته 1.\rفإن قلت: التصديق إنما يكون بعد التصور، والإيمان إنما يكون بعد التفهم؛ فهذه الألفاظ إذا لم يفهم العبد معانيها ...\rكيف يعتقد صدق قائلها فيها؟\rفجوابك: أن التصديق بالأمور الجملية ليس بمحال؛ وكل عاقل يعلم أنه أريد بهذه الألفاظ المعاني، وأن كل اسم فله\r_________________\r(1) وقد روى الحاكم في المستدرك (514/ 2)، والبيهقي في \"الشعب (208) عن سيدنا انس بن مالك رضي الله عنه أنه سمع عمر بن الخطاب رضي الله عنه يقرأ: {فَأَنْبَتْنَا فِيهَا حَبًّا (27) وَعِنَبًا وَقَضْبًا (28) وَزَيْتُونًا وَنَخْلًا (29) وَحَدَائِقَ غُلْبًا (30) وَفَاكِهَةً وَأَبًّا (} [عبس: 27 - 31]، قال: فكل هذا قد عرفناه، فما الأب؟ ثم نفض عصا كانت في يده فقال: (هذا لعمر الله التكلف، اتبعوا ما تبين لكم من هذا الكتاب)."], [58, "مسمى, إذا نطق به من أراد مخاطبة قوم ... قصد ذلك المسمى؛ فيمكنه أن يعتقد كونه كاذبا مخبرا عنه على خلاف ما هو عليه؛\rويمكنه أن يعتقد كونه صادقا مخبرا عنه على ما هو عليه، فهذا معقول على سبيل الإجمال.\rبل يمكن أن يفهم من هذه الألفاظ أمور جملية غير مفصلة، ويمكن التصديق كما لو قال في البيت حيوان ...\rأمكن أن يُصدَّقَ دون أن يعرف أنه إنسان أو فرس أو غيره، بل لو قال: فيه شيء .. أمكن تصديقه وإن لم يعرف ذلك الشيء. فكذلك من سمع الاستواء على العرش .. فهم على الجملة: أنه أريد بذلك نسبة خاصة للعرش، فيمكنه التصديق قبل أن يعرف أن تلك النسبة هي نسبة الاستقرار عليه، أو الإقبال على خلقه وايجاده, أو الاستيلاء عليه, أو معنى آخر من معاني النسبة 1,\rفأمكن التصديق به،\rفإن قلت: فأي فائدة في مخاطبة الخلق بما لا يفهمون؟\rفجوابك: أنه قصد بهذا الخطاب تفهيم من هو أهله؛ وهم الأولياء والراسخون من العلماء، وقد فهموا، وليس\r________________\r1) انظر تحقيق هذه النّسب في \"الإقتصاد في الإعتقاد\" للإمام الغزالي رحمه الله تعالى (ص 174)"], [59, "من شرط من يخاطب العقلاء بكلام أن يخاطبهم بما يفهمه الصبيان، والعوامُّ بالإضافة إلى العارفين كالصبيان بالإضافة إلى البالغين، ولكن على الصبيان أن يسألوا البالغين عما لم يفهمونه، وعلى البالغين أن يجيبوا الصبيان بأن هذا ليس من شأنكم, ولستم من أهله, فخوضوا في حديث غيره؛ فقد قيل للجاهل: فَسْئَلُوا أَهْلَ الذِّكْرِ [النحل: 43].\rفإذا سألوا أهل الذكر؛ فإن كانوا يطيقون فهمه ... فهَّموهم، وإلا قالوا لهم: {وَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلَّا قَلِيلًا} [الإسراء: 85].\r{لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ} [المائدة: 101] ما لكم ولهذا السؤال؟! هذه\rمعان الإيمان بها واجب, والكيفية مجهولة, أي لكم، والسؤال عنه بدعة؛ كما قال مالك رضي الله عنه: (الاستواء معلوم,\rوالكيفية مجهولة, والإيمان به واجب، والسؤال عنه بدعة).\rفإذاً الإيمان بالجمليات التي ليست مفصلة في الذهن ممكن, ولكن تقديسه - الذي هو نفي للمحال عنه ينبغي أن يكون مفصلا، فإن المنفىَّ هي الجسمية ولوازمها.\rونعني بالجسم هاهنا: الشخص المقدر، الطويل العريض العميق، الذي يمنع غيره من أن يوجد بحيث هو, الذي يدفع"], [60, "ما يطلب مكانه إن كان قويا, ويندفع ويتنحَّى عن مكانه بقوة دافعة إن كان ضعيفا، وإنما شرحنا هذا اللفظ مع ظهوره,\rلأن العامي ربما لا يفهم المراد به."], [61, "الوظيفة الثالثة: الاعتراف بالعجز\r"]], "pg": [57, 61]}, "448.6": {"x": [[61, "ويجب على كل من لا يقف على كنه هذه المعاني وحقيقتها, ولم يعرف تأويلها والمعنى والمراد بها .. أن يقر بالعجز؛\rفإن الصدق واجب، وهو عن دركه عاجز.\rفإن ادعى المعرفة .. فقد كذب, وهذا معنى قول مالك رضي الله عنه: (الكيفية مجهولة) يعني: تفصيل المراد به غير معلوم.\rبل الراسخون في العلم والعارفون من الأولياء إن جاوزوا في المعرفة حدود العوام, وجالوا في ميدان المعرفة, وقطعوا من بواديها أميالا كثيرة .. فما بقي لهم مما لم يبلغوه هو بين أيديهم أكثر, بل لا نسبة لما طوى عنهم إلى ما كشف لهم؛ لكثرة المطوى وقلة المكشوف بالإضافة إليه.\rوالإضافة إلى المطوي المستور: قال سيد الأنبياء صلوات اللّه عليه وسلامه: \"لا أحصى ثناء عليك أنت كما اثنيت على نفسك\"1.\r______________\r(1) رواه مسلم (486) عن سيدتنا عائشة رضي الله عنها، قال الإمام الغزالي رحمه الله تعالى: (وليس المعنى أني أعجز عن التعبير عما أدركته، بل هو اعتراف بالقصور عن إدراك كنه جلاله، ولذلك قال بعضهم: «ما عرفت الله بالحقيقة سوى الله عز وجل»)، وانظر تفصيل ذلك في الإحياء، (369/ 1)."], [62, "وبالإضافة إلى المكشوف: قال صلى اللّه عليه وسلم: \"أعرفكم بالله أخوفكم للّه وأنا أعرفكم بالله\"1.\rولأجل كون العجز والقصور ضروريا في آخر الأمر بالإضافة إلى منتهى الحال 2 .. قال سيد الصديقين رضي الله عنه وأرضاه:\r(العجز عن درك الإدراك إدراك) 3.\rفأوائل حقائق هذه المعاني بالإضافة إلى عوام الخلق كأواخرها بالإضافة إلى خواص الخلق، فكيف لا يجب عليه الاعتراف بالعجز؟!.\r___________________\r(1) أخرجه البخاري (5063) عن سيدنا أنس رضي الله عنه بلفظ: «أما والله إني لأخشاكم لله وأتقاكم» وأخرجه أيضا (20) عن سيدتنا عائشة رضي الله عنها بلفظ: «إن أتقاكم وأعلمكم بالله .. أنا» وانظر «إتحاف السادة المتقين» (198/ 9).\r2) في (د، ه): (بالإضافة إلى منتهى الجلال) ومعناها ظاهر.\r3) أورده الطوسي في «اللمع» (ص 57)، والخركوشي في «تهذيب الأسرار» (ص 53)"], [63, "الوظيفة الرابعة: السكوت عن السؤال\r"]], "pg": [61, 63]}, "448.7": {"x": [[63, "وذلك واجب على العوام؛ لأنه بالسؤال متعرض لما لا يطيقه, وخائض فيما ليس أهلا له.\rفإن سأل جاهلا .. زاده جوابه جهلا, وبما ورطه في الكفر من حيث لا يشعر.\rوإن سأل عارفا .. عجز العارف عن تفهيمه لقصور فهمه عجز البالغ عن تفهيم ولده الصبي مصالح بيته وتدبيره. بل عجز عن تفهيمه مصلحته في خروجه إلى المكتب، بل عجز الصائغ عن تفهيم النجار دقائق صياغته، فإن النجار وإن كان بصيرا بصناعته .. فهو عاجز عن دقائق الصياغة؛ لأنه إنما يعلم دقائق النجر لاستغراقه العمر في تعلمه وممارسته، وكذلك يفهم الصائغ الصياغة أيضا بصرف العمر إلى تعلمها وممارستها، وقبل ذلك لا يفهمها.\rفالمشغولون بالدنيا، وبالعلوم التي ليست من قبيل معرفة اللّه نعالى .. عاجزون عن معرفة الأمور الإلهية عجزَ كافة المعرضين عن الصناعات عن فهمها، بل عجز الصبي الرضيع عن الاغتذاء بالخبز واللحم, لقصور في فطرته, لا لعدم الخبز واللحم, ولا"], [64, "لأنه قاصر على تغذية الأقوياء 1، لكن طبع الضعفاء قاصر عن التغذي به.\rفمن أطعم الصبي الضعيف الخبز واللحم, أو مكنّه من تناوله .. فقد أهلكه، وكذلك العامي إذا طلب بالسؤال هذه المعاني .. وجب زجره ومنعه وضربه بالدِّرَّة ِ كما كان يفعله عمر رضي اللّه عنه بكل من سأل عن الآيات المتشابهة 2، وكما فعله رسول اللّه صلى اللّه عليه وسلم في الإنكار على قوم رآهم خاضوا في مسألة القدر وسألوا عنه، فقال صلى اللّه عليه وسلم: \"أبهذا أمرتم؟! 3\" وقال عليه السلام: \"إنّما هلك من كان قبلكم بكثرة السّؤال\" أو لفظ هذا معناه كما اشتهر في الخبر 4.\rولهذا أقول: يحرم على الوعاظ على رءوس المنابر الجواب\r___________________\r(1) في (ب): (ولا؛ لأنه قاصر عن الاغتذاء به).\r(2) فقد روى الدارمي في \"سننه (146) عن سليمان بن يسار: أن رجلا قال له: صبيغٌ قدم المدينة، فجعل يسال عن متشابه القرآن، فأرسل إليه عمر رضي الله عنه وقد أعد له عراجين النخل، فقال: (من أنت؟) قال: أنا عبد الله صبيغ، فأخذ عمر عرجونا من تلك العراجين، فضربه، وقال: (أنا عبد الله عمر)، فجعل له ضربة حتى دمي رأسه، فقال: يا أمير المؤمنين؛ حسبك؛ قد ذهب الذي كنت أجد في رأسي، وعنده في سننه أيضا (150): فقال صبيغ: إن كنت تريد قتلي .. فاقتلني قتلا جميلا، وإن كنت تريد أن تداويني .. فقد - والله - برأت، فأذن له إلى أرضه، وكتب إلى أبي موسى الأشعري رضي الله عنه (ألا يجالسه أحد من المسلمين)، فاشتد ذلك على الرجل، فكتب أبو موسى إلى عمر: أن قد حسنت توبته، فكتب عمر: (أن ائذن للناس بمجالسته).\r(3) رواه الترمذي (2123) عن سيدنا أبي هريرة رضي الله عنه، وابن ماجه (93) عن سيدنا عبد الله بن عمرو رضي الله عنهما.\r(4) رواه مسلم (1337) عن سيدنا أبي هريرة رضي الله عنه بنحوه.\r*"], [65, "عن هذه الأسولة 1 بالخوض في التأويل والتفصيل، بل الواجب عليهم الاقتصار على ما ذكرناه وذكره السلف، وهو المبالغة في التقديس والتنزيه ونفي التشبيه، وأنه تعالى منزه عن الجسمية وعوارضها.\rوله المبالغة في هذا بما أراد؛ حتى يقول: كل ما خطر ببالكم، وهجس في ضميركم, وتصور في خاطركم .. فالله تعالى خالقها؛ وهو منزه عنها وعن مشابهتها, وأنّه ليس المراد بالأخبار شيئا من ذلك، وما هو حقيقة المراد .. فلستم من أهل معرفتها والسؤال عنها، فاشتغِلوا بالتقوى؛ فما أمركم اللّه تعالى به .. فافعلوه، وما نهاكم عنه .. فاجتنبوه, وهذا قد نهُيتُم عنه فلا تسألوه, ومهما سمعتم شيئا من ذلك فاسكتوا وقولوا: آمنا وصدقنا وما أوتينا من العلم إلا قليلا، وليس هذا من جملة ما أوتينا.\r________________\r1) حكي عن ابن جني: سؤال وأسولة؛ باتسهيل، وفي (د، ه): (المسائل)"], [66, "الوظيفة الخامسة: الإمساك عن التصرف في ألفاظ واردة\r"]], "pg": [63, 66]}, "448.8": {"x": [[66, "يجب على عموم الخلق الجمود على ألفاظ هذه الأخبار، والإمساك عن التصرف فيها من ستة أوجه: التفسير، والتأويل، والتصريف، والتفريع، والجمع، والتفريق.\rالأول: التفسير\r"]], "pg": [66, 66]}, "448.9": {"x": [[66, "وأعني به تبديل اللفظ بلغة أخرى يقوم مقامها في العربية أو معناها بالفارسية أو التركية 1، بل لا يجوز النطق إلا باللفظ الوارد، لأن من الألفاظ العربية: ما لا يوجد لها فارسية تطابقها.\rومنها ما يوجد لها فارسية تطابقها لكن ما جرت عادة الفرس باستعارتها للمعاني التي جرت عادة العرب باستعارتها فيها.\rومنها ما يكون مشتركا في العربية ولا يكون في العجمية كذلك.\rأما الأول: فمثاله: لفظ (الاستواء) فإنه ليس له في الفارسية لفظ مطابق يؤدي بين الفُرْسِ المعنى الذي يؤديه لفظ الاستواء بين العرب بحيث لا يشتمل على مزيد إيهام؛ إذ فارسيته أن يقال (راست باستاد).\r_____________________\r1) في (د): (أو بمعناها)."], [67, "وهذان لفظان: الأول: ينبئ عن انتصاب واستقامة فيما يتصور أن ينحني ويعوج.\rوالثاني: ينبئ عن سكون وثبات فيما يتصور أن يتحرك ويضطرب, وإشعاره بهذه المعاني وإشارته إليها في\rالعجمية أظهر من إشعار لفظ (الاستواء) وإشارته إليها، فإذا تفاوتا في الدلالة والإشعار .. لم يكن هذا مثل الأول.\rوإنما يجوز تبديل اللفظ بمثله المرادف له, الذي لا يخالفه بوجه من الوجوه, لا بما يباينه ويخالفه ولو بأدنى شيء وأدقِّهِ وأخفاه.\r\rومثال الثاني: أن (الإصبع) يستعار في لسان العرب للنعمة؛ يقال لفلان عندي إصبع؛ أي نعمة، ومعناها بالفارسية؛ (أَنْكُشْتَ)،\rوما جرت عادة العجم بهذه الاستعارة، وتوسع العرب في التجوز والاستعارة أكثر من توسع العجم، بل لا نسبة لتوسع العرب إلى جمود العجم.\rفإذا حسن إرادة المعنى المستعار له في العرب وسمج ذلك في العجم .. نفر القلب عما سمج, ومجه السمع ولم يمل إليه، فإذا تفاوتا لم يكن التفسير تبديلا بالمثل بل بالخلاف ولا يجوز التبديل إلا بالمثل."], [68, "مثال الثالث: لفظ (العين) فإن من فسره إنما فسره بأظهر معانيه، فيقول بالفارسية: (چشم) وهو مشترك في لغة العرب بين\rالعضو الباصر وعين الماء والذهب والشمس، وليس اللفظ (چشم) هذا الاشتراك.\rوكذلك لفظ (الجنب) و (الوجه) يقرب منه، ولأجل هذا نرى المنع من التبديل, والاقتصار على العربية.\rفإن قيل: هذا التفاوت إن ادعيتموه في جميع الألفاظ .. فهو غير صحيح, إذ لا فرق بين قولك: (خبز) و (نان) , وبين قولك (لحم) و (گوشت)، وإن اعترفت بأن ذلك في البعض .. فامنع من التبديل عند التفاوت، لا عند التماثل.\rفالجواب: الحق أن هذا التفاوت في البعض لا في الكل,\rفلعل لفظ (اليد) ولفظ (دست) يتساويان في اللغتين وفي الاشتراك والاستعارة وسائر الأمور, ولكن إذا انقسم إلى ما يجوز وإلى ما لا يجوز, وليس إدراك التمييز بينهما والوقوف على دقائق التفاوت جليا سهلا يسيرا على كافة الخلق, بل يكثر فيه الإشكال, ولا يتميز محل التفاوت عن محل التعادل .. فنحن بين أن نحسم الباب احتياطا - إذ لا حاجة ولا ضرورة إلى التبديل - وبين أن نفتح الباب ونقحم عموم الخلق ورطة الخطر."], [69, "فليت شعري! أي الأمرين أحزم وأحوط، والمتصرف فيه ذات الإله وصفاته؟!\rوما عندي أن عاقلا متدينا لا يقر بأن هذا الأمر مخطر، وأن الخطر في الصفات الإلهية يجب اجتنابه.\rكيف وقد أوجب الشرع على الموطوءة العِدّةَ البراءة الرحم،\rوالحذر مِنْ خلط الأنساب, احتياطاً لحكم الولاية والوراثة وما يترتب على النسب؛ فقالوا مع ذلك تجب العدة على العقيم\rوالآيسة والصغيرة وعند العزل؛ لأن باطن الأرحام إنما يطلع عليها علام الغيوب؛ فإنه يعلم ما في الأرحام، فلو فتحنا باب النظر إلى التفصيل .. كنا راكبين متن الخطر؛ فإيجاب العدة حيث لا علوق أهون من ركوب هذا الخطر.\rفكما أن إيجاب العدة حكم شرعي .. فتحريم تبديل العربية حكم شرعي، ثبت بالاجتهاد وترجيح طريق الأولى 1، ويعلم أن هذا الاحتياط في الخبر عن اللّه تعالى وعن صفاته وعما أراده بألفاظ القرآن .. أهمُ وأولى من الاحتياط في العدة ومن كل ما احتاط به الفقهاء من هذا القبيل.\rأما التصرف الثاني: التأويل،\r"]], "pg": [66, 69]}, "448.10": {"x": [[69, "وهو بيان معناه بعد إزالة ظاهره؛ وهذا إما يقع من\r______________\r1) في (ب): (وترجيح طريق على طريق من حيث الأولى)."], [70, "العامي نفسه، أو من العارف مع العامي، أو من العارف مع نفسه بينه وبين ربه، فهذه ثلاثة مواضع.\rالأول: تأويل العامي على سبيل الاستقلال بنفسه، وهو حرام، يشبه خوض البحر المغرق ممن لا يحسن السباحة، ولا شك في تحريمه، وبحر معرفة اللّه أبعد غورا وأكثر معاطب ومهالك من بحر الماء؛ لأن هلاك هذا البحر لا حياة بعده، وهلاك بحر الدنيا لا يزيل إلا الحياة الزائلة، وذلك يزيل الحياة الأبدية فشتان بين الخطرين.\rالموضع الثاني: أن يكون ذلك من العالم مع العامي 1، وهو أيضا ممنوع، ومثاله: أن يجر السباح الغواص في البحر مع نفسه ..\rعاجزا عن السباحة، مضطرب القلب والبدن، وذلك حرام، لأنه عرّضة لخطر الهلاك؛ فإنه لا يقوى على حفظه في لُجَّة البحر، وإن قدر على حفظه في القرب من الساحل، ولو أمره بالوقوف بقرب الساحل .. لا يطيعه، وإن أمره بالسكون عند التطام الأمواج واقبال التماسيح وقد فغرت فاها للالتقام .. اضطرب قلبه وبدنه, ولم يسكن على حسب مراده؛ لقصور طاقته؛ وهذا هو المثال الحق للعالم إذا فتح للعامي باب التأويلات والتصرف في خلاف الظواهر 2.\r__________________\r1) وذلك بفتح باب المباحثة معه.\r2) فلا ينبغي أن يخاض مع العوام في حقائق العلوم الدقيقة، بل يقتصر معهم على تعليم ="], [71, "وفي معنى العوام: الأديب, والنحوي, والمحدث, والمفسر, والفقيه, والمتكلم, بل كل عالٍم, سوى المتجردين لعلم السباحة في بحار المعرفة, القاصرين أعمارهم عليه، الصارفين وجوههم عن الدنيا والشهوات، المعرضين عن المال والجاه والخلق وسائر اللذات، المخلصين للّه تعالى في العلوم والأعمال، بجميع حدود الشريعة, وآدابها في القيام بالطاعات وترك المنكرات، المفرغين قلوبهم بالجملة عن غير اللّه للّه، المستحقرين للدنيا بل الآخرة والفردوس الأعلى في جنب محبة اللّه تعالى، فهؤلاء هم أهل الغوص في بحر المعرفة.\rوهم مع ذلك كله على خطر عظيم؛ يهلك من العشرة تسعة إلى أن يسعد واحد بالدر المكنون والسر المخزون، أولئك الذين سبقت لهم من اللّه الحسنى فهم الفائزون: ورَبُّكَ يَعْلَمُ ما تُكِنُّ صُدُورُهُمْ وما يُعْلِنُونَ [القصص: 69].\rالموضع الثالث: تأويل العارف مع نفسه في سر قلبه بينه وبين ربه؛ وهو على ثلاثة أوجه؛ فإن الذي انقدح في سره أنه المراد من لفظ (الاستواء) و (الفوق) مثلا: إما أن يكون\r_____________________\r= العبادات، وتعليم الأمانة في الصناعات التي هم بصددها، ويملأ قلوبهم من الرغبة والرهبة في\rالجنة والنار كما نطق به القرآن، ولا يحرك عليهم شبهة ... ، وبالجملة: لا ينبغي أن يفتح للعوام باب البحث في المشتبهات؛\rفإنه يعطل عليهم صناعاتهم التي بها قوام الخلق، ودوام عيش الخواص. «الإحياء» (215/ 1)."], [72, "مقطوعا به، أو مشكوكا فيه، أو مظنونا ظنا غالبا.\rفإن كان قطعيا .. فليعتقده، وإن كان مشكوكا .. فليجتنبه, ولا يحكمن على مراد اللّه تعالى ورسوله صلى اللّه عليه وسلم من كلامه باحتمال يعارضه مثله من غير ترجيح، بل الواجب على الشاك التوقف.\rوإن كان مظنونا .. فاعلم أن للظن متعلقين:\rأحدهما: أن المعنى الذي انقدح عنده هل هو جائز في حق اللّه تعالى أم هو محال؟\rوالثاني: أن يعلم قطعا جوازه، لكن تردد في أنه هل هو مراد باللفظ أم لا؟\rمثاله: تأويل لفظ (الفوق) بالعلو المعنوي الذي هو المراد بقولنا: (السلطان فوق الوزير)، فإنا لا نشك في ثبوت معناه للّه تعالى،\rلكنا ربما نتردد في أن لفظ (الفوق) في قوله تعالى: يَخافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ [النحل: 50]. هل أريد به العلو المعنوي أم أريد به معنى آخر يليق بجلال اللّه تعالى دون العلو بالمكان الذي هو محال على ما ليس بجسم ولا هو صفة في جسم؟\rومثال الثاني 1: تأويل لفظ (الاستواء على العرش)، بأنه أراد به النسبة الخاصة التي للعرش 2 ونسبته: أن اللّه تعالى\r________________\r1) الذي هو الأوّل في العدّ؛ وهو ما تردد فيه أهو جائز أو محال، فلينتبه.\r2) في (أ، ب, و): (الحاصلة الى العرش)."], [73, "يتصرف في جميع العالم ويدبر الأمر من السماء إلى الأرض بواسطة العرش فإنه لا يحدث في العالم صورة ما لم يحدثه في العرش، كما لا يحدث النقاش والكاتب صورة وكلمة على البياض ما لم يحدثه في الدماغ، بل لا يحدث البناء صورة البناء ما لم يحدث صورته في الدماغ، فبواسطة الدماغ يدبر القلب أمر عالمه الذي هو بدنه.\rفربما يتردد في أنّ إثبات هذه النسبة للعرش إلى اللّه تعالى هل هو جائز: إما لوجوبه في نفسه، وإمّا على سبيل أن يقال: أجرى به سنته وعادته وإن لم يكن خلافه محالا؛ كما أجرى عادته في حق قلب الإنسان؛ بألا يمكِّنه من التدبير إلا بواسطة الدماغ،\rوإن كان في قدرة اللّه تعالى تمكينه منه دون الدماغ لو سبقت به إرادته الأزلية وحقت به الكلمة القديمة التي هي علمه،\rفصار خلافه ممتنعا لا لقصور في ذات القدرة لكن لاستحالة ما يخالف الإرادة القديمة والعلم السابق الأزلي، ولذلك قال تعالى:\rوَلَنْ تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا [الأحزاب: 62، الفتح: 23]. وإنما لا تتبديل لوجوبها, وإنما وجوبها لصدورها عن إرادة أزلية واجبة، ونتيجة الواجب واجب، ونقيضه محال وإن لم يكن محالا في ذاته، ولكنه محال لغيره وهو إفضاؤه إلى أن ينقلب العلم الأولي جهلاً ويمتنع نفوذ المشيئة الأزلية."], [74, "فإذاً؛ إثبات هذه النسبة لله تعالى مع العرش في تدبير المملكة بواسطته إن كان جائزاً عقلاً .. فهل هو واقع وجوداً؟\rهذا مما قد يتردد فيه الناظر، وربما يظن وجوده, هذا مثال الظن في نفس المعنى، والأول مثال الظن في كون المعنى مراداً باللفظ مع كون المعنى في نفسه صحيحاً جائزاً، وبينهما فرقان 1؛ لأن كل واحد من الظنين إذا انقدح في النفس وحاك في الصدر فلا يدخل تحت الاختيار دفعه عن النفس، ولا يمكنه ألا يظن؛ فإن للظن أسباباً ضروريةً لا يمكن دفعُها، ولا يكلف الله نفساً إلا وسعها؛ لكن عليه وظيفتان جديدتان:\rإحداهما: أن لا يدع نفسه تطمئن إليه جزماً من غير شعور بإمكان الغلط فيه، ولا ينبغي أن يحكم من نفسه بموجب ظنه حكماً جازماً.\rوالثانية: أنه إن ذكره لم يطلق القول بأن المراد ب (الاستواء) كذا، أو المراد ب (الفوق) كذا؛ لأنه حكم بما لا يعلم، وقد قال الله تعالى: {وَلا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ} [الإسراء: 36]، لكن يقول: أنا أظن أنه كذا، فيكون صادقاً في خبره عن نفسه وعن ضميره، ولا يكون حكماً على صفة الله ولا على مراده بكلامه، بل حكماً على نفسه، ونبأً عن ضميره.\r_________________\r1) في (ب، ه): (وبينهما تفاوت)."], [75, "فإن قيل: وهل يجوز ذكر هذا الظن مع كافة الخلق والتحدث به كما اشتمل عليه ضميره؟ وكذلك لو كان قاطعاً .. فهل له أن يتحدث به؟\rقلنا: تحدثه به إنما يكون على أربعة أوجهٍ: فإنه فإما أن يكون مع نفسه، أو مع من هو مثله في الاستبصار، أو مع من هو مستعد للاستبصار بذكائه وفطنته وتجرده لطلب معرفة الله تعالى، أو مع العامي.\rفإن كان قاطعاً: فله أن يحدث نفسه به، ويحدث من هو مثله في الاستبصار، أو من هو متجرد لطلب المعرفة مستعد لها، خَالٍ عن الميل إلى الدنيا والشهوات والتعصبات للمذاهب وطلب المباهاة بالمعارف والتظاهر بذكرها مع العوام، فمن اتصف بهذه الصفات: فلا بأس بالتحدث معه؛ لأن الفَطِنَ المتعطش إلى المعرفة - للمعرفة لا لغرض آخر- يحيك فى صدره إشكال الظواهر، وربما يلقيه في تأويلات فاسدة؛ لشدة شرهه على الفرار عن مقتضى الظواهر، ومنع العلم أهله ظلمٌ؛ كبثه إلى غير أهله.\rوأما العامي: فلا ينبغي أن يحدَّث به، وفي معنى العامي كُلُّ من لا يتصف بالصفات المذكورة، بل مثاله ما ذكرناه من إطعام الرضيع الأطعمةَ القويةَ التي لا يطيقها. وأما المظنون .. فتحدثه مع نفسه اضطرار؛ فإن ما ينطوي"], [76, "عليه الذهن؛ من ظنٍّ وشكٍّ وقطع لا تزال النفس تتحدث به، ولا قدرة على الخلاص منه ولا منع منه، ولا شك في منع التحدث به مع العوام، بل هو أولى بالمنع من المقطوع.\rأما تحدثه مع من هو في مثل درجته في المعرفة، أو مع المستعد له .. ففيه نظر:\rفيُحتمَلُ أن يُقال: هو جائز؛ ولا يزيد على أن يقول: (أظن كذا)، وهو صادق.\rفيحتمل المنع؛ لأنه قادر على تركه، وهو بذكره متصرِّف بالظن في صفة الله تعالى أو في مراده من كلامه، وفيه خطر 1،\rوإباحته تُعرف بنص أو إجماع أو قياس على منصوص، ولم يَرِد شيء من ذلك، بل ورد قوله تعالى: {وَلا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ} [الإسراء: 36].\rفإن قيل: يدل على الجواز ثلاثةُ أمور:\rالأول: الدليل الذي دل على إباحة الصدق، وهو صادق؛ فإنه ليس يخبر إلا عن ظنه وهو ظان.\rوالثاني: أقاويل المفسرين في القرآن بالحَدْسِ والظن؛ إذ كل ما قالوه غيرُ مسموع من الرسول صلى الله عليه وسلم بل هو\r______________\r1) في (ب، ه): (نظر)."], [77, "مستنبط بالاجتهاد؛ ولذلك كثرت الأقاويل وتعارضت.\rوالثالث: إجماع التابعين على نقل الأخبار المتشابهة التي\rنقلها آحادُ الصحابةِ ولم تتواتر 1، وما اشتمل عليه الصحيحُ\rالذي نقله العدل عن العدل فإنهم جوَّزوا روايته، ولا يحصل بقول العدل إلا الظن.\rوالجواب عن الأول: أن المباح صدق لا يُخشى منه ضرر، وبثُّ هذه الظنون لا يخلو عن ضرر، فقد يسمعه من يسكن إليه ويعتقده جزماً، فيحكم في صفات الله تعالى بغير علم، وهو خطر. والنفوس نافرة عن إشكال الظواهر، فإذا وجد مستروحاً من المعنى ولو مظنوناً .. سكن إليه واعتقده جزماً، وربما يكون غلطاً، فيكون قد اعتقد في صفات الله تعالى ماهو الباطل، أو حكم عليه في كلامه بما لم يرد به.\rوأما الثاني: وهو أقاويل المفسرين بالظن: فلا نُسلِّمُ ذلك فيما هو من صفات الله تعالى؛ كالاستواء والفوق وغيره، بل لعل ذلك في الأحكام الفقهية، أو في حكايات أحوال الأنبياء أو\r_____________\r(1) لا يرتضي الإمام الغزالي رحمه الله تعالي تسمية هذه الأخبار بالمتشابه، وإنما سماها هنا بذالك على لسان المعترض، قال في «الاقتصاد (ص 123) عند حديثه عن هذه الأخبار: (فكيف يقال: إنه متشابه؟! بل هو مخيل معنى خطأ عند الجاهل، ومُفهِمٌ معنى صحيحا عند العالم)، وقال في «المستصفى، (107/ 1) رداً على من سماها بالمتشابه: (هيهات! فإن هذه کنايات واستعارات يفهمها المؤمنون ... )."], [78, "الكفار, أو المواعظ والأمثال وما لا يَعْظُمُ خطر الخطأ فيه.\rوأما الثالث: فقد قال قائلون: لا يجوز أن يعتمد في هذا الباب إلا ما ورد في القرآن، أو تواتر عن الرسول صلى الله عليه وسلم تواتراً يفيد العلم، فأما أخبار الآحاد .. فلا يُقبل فيه، ولا يشتغل بتأويله عند من يميل إلى التأويل، ولا بروايته عند من يقتصر على الرواية، لأن ذلك حكمٌ بالمظنون واعتمادٌ عليه.\rوما ذكروه ليس ببعيد، لكنه مخالف لظاهر ما درج عليه السلف، فإنهم قبلوا هذه الأخبار من العدول ورووها وصححوها.\rفالجواب من وجهين:\rأحدهما: أن التابعين كانوا قد عرفوا من أدلة الشرع أنه لا يجوز اتهام العدل بالكذب، لا سيما في صفات الله تعالى؛ فإذا روى الصديق رضي الله عنه خبراً، وقال: سمعت رسول الله صلى الله عليه وسلم يقول كذا .. فَرَدُّ روايته تكذيبٌ له، ونسبةٌ له إلى الوضع أو إلى السهو، فقبلوه وقالوا: قال أبو بكر: قال رسول الله صلى الله عليه وسلم، قال أنس: قال رسول الله صلى الله عليه وسلم، وكذا في التابعين.\rفالآن إذا ثبت عندهم بأدلة الشرع أنه لا سبيل إلى اتهام العدل التقي من الصحابة 1 .. فمن أين يجب أن لا يُتهم ظنونُ الآحاد,\r__________\r(1) قوله: (العدل التفي من الصحابة) صفة لازم كما يفهم من عامة كتبه، ويوهم أن يكون مذهبه كمذهب المازري القائل بالتحري عن عدالة من لم تطل صحبته وتشتهر."], [79, "وأن يُنزّل الظَّنُّ منزلةَ نقل العدل مع أن بعض الظن أثم؟!\rفإذا قال الشارع: ما أخبركم به العدل فصدقوه واقبلوه، وانقلوه وأظهروه .. فلا يلزم من هذا أن يقال: ما حدثتْكم به نفوسُكم من ظنونكم .. فاقبلوه وأظهروه، وارووا عن ظنونكم وضمائركم ونفوسكم ما قالته؛ فليس هذا في معنى المنصوص.\rولهذا نقول: ما رواه غير العدل من هذا الجنس .. ينبغي أن يُعرض عنه ولا يُروى، ويُحتاط فيه أكثر مما يحتاط في المواعظ والأمثال وما يجري مجراها.\rوالجواب الثاني: أن تلك الأخبار روتها الصحابة، لأنهم سمعوه يقيناً, فما نقلوا إلا ما تيقنوه، والتابعون قبلوه ورووه، وما قالوا:\rقال رسول الله صلى الله عليه وسلم كذا، بل قالوا: قال فلان: قال رسول الله صلى الله عليه وسلم كذا، وكانوا صادقين، وما أهملوا روايته، لاشتمال كل حديث على فوائد سوى اللفظ الموهم, ولإفادة اللفظ الموهم عند العارف معنىً حقيقياً يفهمه منه،\rليس ذلك ظنياً فى حقه.\rمثاله رواية الصحابي عن رسول الله صلى الله عليه وسلم قوله: (ينزل الله تعالى كل ليلة إلى السماء الدنيا، فيقول: هل من داع فأستجيب له؟ هل من مستغفر فأغفر له؟ .. ) الحديث 1.\r_______________\r1) رواه مسلم (758) عن سيدنا أبي هريرة رضي الله عنه بنحوه."], [80, "فهذا الحديث سيق لنهاية الترغيب في قيام الليل، وله تأثير عظيم في تحريك الدواعي للتهجد الذي هو أفضل العبادات،\rفلو تُرِكَ نقل هذا الحديث .. لبطلتْ هذه الفائدة العظيمة، ولا سبيل إلى إهمالها.\rوليس فيه إلا إيهام لفظ النزول عند الصبي أو عند العامي الجاري مجرى الصبي، وما أهون على البصير أن يغرس في قلب العامي التنزيهَ والتقديسَ عن صورة النزول؛ بأن يقول له: إن كان نزولُه إلى السماء الدنيا لِيُسْمِعَنَا نداءَه وقولَه .. فما أسمعنا!!\rفأي فائدة في نزوله؟! ولقد كان يمكنه أن ينادينا كذلك وهو على العرش أو على السماء العليا!! فهذا القدر يُعَرِّفُ العاميَّ أن ظاهر النزول باطلٌ.\rبل مثاله: أن يريد من في المشرق إسماعَ شخص في المغرب ومناداته، فيتقدّم إلى جهة المغرب بأقدام معدودة وأخذ يناديه وهو\rيعلم أنه لا يسمعه، فيكون نقله الأقدام عملاً باطلاً، وفعلاً كفعل المجانين؛ فكيف يستقر مثل هذا في قلب عاقل؟!\rبل يضطر بهذا القدر كُلُّ عامي إلى أن يتيقَّن نفي صورة النزول، وكيف وقد علم استحالة الجسمية عليه، واستحالةُ الانتقال على غير الأجسام, واستحالة النزول من غير انتقال؟!\rفإذاً؛ الفائدةُ في نقل هذه الأخبار عظيمةٌ, والضررُ يسيرٌ،"], [81, "فأنى يساوي هذا حكايةَ الظنون المنقدحة في الأنفس؟!\rفهذه سبل تجاذب طرق الاجتهاد في إباحة ذكر التأويل المظنون أو المنع.\rولا يبعُدُ ذكر وجه ثالث؛ وهو أن ينظر إلى قرائن حال السائل والمستمع؛ فإن علم أنه ينتفع به .. ذكره، وإن علم أنه يتضرر به .. تركه، وإن ظنَّ أحدَ الأمرين .. كان ظنه كالعلم في إباحة الذكرِ.\rوكم من إنسان لا تتحرَّكُ داعيته باطناً إلى معرفة هذه المعاني, ولا يحيك في نفسه إشكال من ظواهرها، فذكر التأويل معه مشوش.\rوكم من إنسان يحيك في نفسه إشكالُ الظاهر, حتى يكاد أن يسوء اعتقاده في الرسول صلوات وسلامه عليه، وينكر\rقوله الموهم 1؛ فمثل هذا لو ذُكِرَ معه الاحتمالُ المظنونُ، بل مجردُ الاحتمالِ الذي ينبو عنه اللفظ .. انتفع به، ولا بأس بذكره معه فإنه دواء لدائه وإن كان داءً في غيره، ولكن لا ينبغي أن يُذكر على رؤوس المنابر؛ لأن ذلك يحرك الدواعي الساكنة من أكثر المستمعين وقد كانوا عنه غافلين, وعن إشكاله منفكين.\r_____________________\rفيه إشارة إلى رأي المعتزلة الرادّين لجملة هذه الأخبار وإن صحت، أو الإصرار على تأويلها بالظن."], [82, "ولما كان زمانُ السلف الأول زمانَ سكون القلوب .. بالغوا في الكف عن التأويل؛ خيفةً من تحريك الدواعي وتشويش القلوب، فمن خالفهم في ذلك 1 .. فهو الذي حرّك الفتنة، وألقى هذه الشكوك فى القلوب مع الاستغناء عنه, فباء بالإثم.\rأما الآن .. وقد فشا ذكره في بعض البلاد، فالعذر في إظهار شيء من ذلك رجاء لإماطة الأوهام الباطلة عن القلوب .. أظهر،\rواللوم عن قائله أقل.\rفإن قيل: فقد فرّقتم بين التأويل المقطوع والمظنون، فبماذا يحصل القطع بصحة التأويل؟\rقلنا بأمرين:\rأحدهما: أن يكون المعنى مقطوعاً ثبوتُه لله تعالى كفوقية المرتبة.\rالثاني: أن لا يكون اللفظ محتملاً إلا لأمرين، وقد بطل أحدهما وتعيّن الثاني.\rمثاله قوله تعالى: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ} [الأنعام: 18]، فإنه قد ظهر في وضع اللسان أنّ (الفوق) لا يحتمل إلا فوقية المكان، أو فوقية الرتبة، وقد بطل فوقية المكان لمعرفة التقديس، لم يبق إلا\r_______________\r1) في (أ، ج، د، و): (في ذلك الزمان)."], [83, "فوقية الرتبة، كما يقال: السيد فوق العبد، والزوج فوق الزوجة، والسلطان فوق الوزير، والله تعالى فوق عباده بهذا المعنى، وهذا كالمقطوع به في لفظ (الفوق)، وأنه لا يُستعمل في لسانُ العرب إلا في هذين المعنيين 1.\rأما لفظ الاستواء إلى السماء وعلى العرش .. فربما لا ينحصر مفهومه في اللغة هذا الانحصار، وإذا تردد بين ثلاثة معان:\rمعنيان جائزان على الله سبحانه، ومعنى واحد وهو الباطل .. فتنزيله على أحد المعنيين الجائزين يكون بالظن أو الاحتمال المجرد.\rوهذا تمام النظر في الكف عن التأويل.\rالتصريف الثالث الذي يجب الإمساك عنه: التصريف.\r"]], "pg": [69, 83]}, "448.11": {"x": [[83, "ومعناه أنه إذا ورد قوله تعالى: {اسْتَوَى عَلَى الْعَرْشِ} .. فلا ينبغي أن يقال مستوٍ ويستوي؛ لأن المعنى يجوز أن يختلف؛ لأن دلالة قوله: (هو مستوٍ على العرش) على الاستقرار أظهر من قوله: {رَفَعَ السَّمَاوَاتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا ثُمَّ اسْتَوَى عَلَى الْعَرْشِ} [الرعد: 2]، و كقوله: {خَلَقَ لَكُم مَّا فِي الْأَرْضِ جَمِيعًا ثُمَّ اسْتَوَى إِلَى السَّمَاءِ} [البقرة: 29]، فإن هذا يدل\r_______________\r(1) ومثل لفظ (الفوق): لفظ (العلو)، وتأمل قوله تعالى: {وَأَنْ لَا تَعْلُوا عَلَى اللَّهِ إِنِّي آتِيكُمْ بِسُلْطَانٍ مُبِينٍ} [الدخان: 19]، وقد يقال: بأتي لفظ (الفرق) بمعنى الأكثر؛ كقوله تعالى: {فَإِنْ كُنَّ نِسَاءً فَوْقَ اثْنَتَيْنِ} [النساء: 11]، وبمعنى الدون؛ كقوله تعالى: {بَعُوضَةً فَمَا فَوْقَهَا} [البقرة: 26]، فالجواب: أن هذه المجازات ترجع عند التأمل لهذين المعنيين اللذين نص عليهما الإمام الغزالي أرضاه الله تعالى."]], "pg": [83, 83]}, "448.12": {"x": [[84, "على استواء قد انقضى؛ من إقبال على خلقه 1، أو على تدبير المملكة بواسطته 2.\rففي تغيير التصاريف ما يؤثر في تغيير الدلالات والاحتمالات، فليجتنبْ التصريفَ كما يجتنبُ الزيادة، فإن تحت التصريف نقصانا او زيادة.\rالتصرف الرابع الذي يجب الإمساك عنه: القياس والتفريع.\rمثل: أن يَرِد لفظ (اليد) فلا يجوز إثبات الساعد والاصبع والكف، مصيراً إلى أن هذا من لوازم اليد 3، وإذا ورد (الأصبع) لم يجز ذكر الأنملة، كما لا يجوز ذكر اللحم والعظم والعصب وإن كانت اليد المشهورة لا تنفك عنه 4.\rوأبعد من هذه الزيادة إثباتُ الرِّجْلِ عند ورود (اليد)، وإثبات الفم عند ورود (العين) أو عند ورود (الضحك)، وإثبات الأذن والعين عند ورود (السمع والبصر)، وكل ذلك محال وكذب\r_______________\r(1) وقد سمع عن العرب: (استوى على بشاتمني) بمعنى: (أقبل علي بشاتمني) انظر تفسير الطبري ه (1/ 251).\r(2) يعني: بواسطة العرش كما سبق بيانه (ص 72 - 73).\r(3) فهو قول باللازم، وهو نوع قياس عند المتكلمين، وهذا القباس من باب قباس الغائب على الشاهد، وهو يفيد الظن لا اليقين عموما، وإن كان ظاهر البطلان هنا، وانظر شرح المواقف» للجرجاني (28/ 2).\r(4) ومنه تدرك خطأ من يتصور عند ذكر اليد والإصبع في حق المولى جل جلاله أن الأصابع جزء من يده؛ قياساً للغائب على الشاهد أيضا."]], "pg": [84, 84]}, "448.13": {"x": [[85, "وزيادة، وقد يتجاسر بعض الحمقى من الحشوية والمشبهة؛ فلذلك ذكرناه.\rالتصرف الخامس: الجمع بين المتفرقات.\rولقد بَعُدَ عن التوفيق من صنَّف كتاباً في جمع الأخبار خاصة، ورسم في كل عضو باباً، فقال: باب في إثبات الرأس، وباب في إثبات اليد، وباب في إثبات العينين .. إلى غير ذلك 1، فإن هذه كلماتٌ متفرقةٌ صدرت من رسول الله صلى الله عليه وسلم في أوقات متفرقة متباعدة؛ اعتماداً على قرائن مختلفة يُفهم السامعين معانيَ صحيحةً.\rفإذا ذُكرت مجموعةً على مثال خلق الإنسان .. صار جمع تلك المتفرقات في السمع دفعةً واحدة عظيمة في تأكيد الظاهر وإيهام التشبيه، وصار الإشكال في أن رسول الله صلى الله عليه وسلم لِمَ نطق بما يوهم خلاف الحق .. أعظم في النفس وأوقع.\rبل الكلمة الواحدة الفردة يتطرق إليها الاحتمال، فإذا انضم اليها ثانية وثالثة ورابعة من جنسها وصار متوالياً .. ضعف الاحتمال بالإضافة إلى الجملة.\rولذلك يحصل من الظن بقول مخبرين وثلاثة ما لا يحصل\r________________\r1) مثل كتاب: ((التوحيد وإثبات صفات الرب عز وجل لابن خزيمة."]], "pg": [85, 85]}, "448.14": {"x": [[86, "بقول الواحد، بل يحصل من العلم القطعي بخبر التواتر ما لا يحصل بالآحاد، ويحصل من العلم القطعي باجتماع القرائن ما لا يحصل بالآاحاد وكل ذلك نتيجة الاجتماع؛ إذ يتطرق الاحتمال إلى قول كل عدل وإلى كل واحدة من القرائن، فإذا اجتمع .. انقطع الاحتمال أو ضعف؛ فلذلك لا يجوز جمع المتفرقات.\rالتصرف السادس: التفريق بين المجتمعات.\rفكما لا يجمع بين متفرقة .. فلا يفرق بين مجتمعة؛ فإن كل كلمة سابقة على كلمة أو لاحقة لها مؤثرةٌ في تفهيم معناه ومرجِّحة الإحتمال الضعيف فيه؛ فإذا فُرقت وفُصلت سقطت دلالتها 1.\rمثاله: قوله تعالى: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ} [الأنعام: 18]، لا يسلّط على أن يقول القائل: (هو فوق) مطلقا؛ لأنه إذا ذكر (القاهر) قبله .. ظهرت دلالةُ الفوق على الفوقية التي للقاهر مع المقهور، وهي فوقية الرتبة، ولفظ (القاهر) يدل عليه.\rبل لا يجوز أن يقول: (وهو القاهر فوق غيره)، بل ينبغي أن يقول: (فوق عباده)؛ لأن ذكر العبودية في وصف من الله تعالى فوقه يؤكد احتمال فوقية السيادة؛ إذ لا يحسن أن تقول: (زيد فوق عمرو)، قبل\r______________\r1) فالعبرة في الفهم لمجمل السياق"], [87, "أن يتبين تفاوتهما 1 في معنى السيادة والعبودية، أو غلبة القهر، أو نفوذ الأمر بالسلطنة، أو بالأبوة أو بالزوجية.\rفهذه دقائق يُغفل عنها العلماء فضلاً عن العوام؛ فكيف يُسلّط العوامُ في مثل ذلك على التصرف بالجمع والتفريق، والتأويل\rوالتفسير، وأنواع التغيير؟!\rولأجل هذه الدقائق بالغ السلف في الجمود والاقتصار على موارد التوقيف كما ورد، على الوجه الذي ورد, وباللفظ الذي ورد، والحق ما قالوه، والصواب ما رأوه.\rفأهم المواضع بالاحتياط ما هو تصرف في ذات الله وصفاته، وأحق المواضع بإلجام اللسان وتقييده عن الجريان ما يعظم فيه الخطر، وأي خطر أعظم من الكفر؟!\r________________\r(1) وفي (ب): (إذ بحسن أن يقول: السيد فوق العبد، والأب فوق الابن، والزوج فوق الزوجة، ولا يحسن أن يقال: زيد فوق عمرو؛ فقد تبين تفاوتهما) أي: في المنزلة والمكانة"], [88, "الوظيفة السادسة: في الكف بعد الإمساك\r"]], "pg": [86, 88]}, "448.15": {"x": [[88, "وأعني بالكف: كَفَّ الباطن عن التفكر في هذه الأمور، فذلك واجب عليه، كما وجب عليه إمساك اللسان عن السؤال والتصرف، وهذا أثقل الوظائف وأشدها.\rوهو واجب كما وجب على العاجز الزَّمِنِ ألا يخوض غمرة البحار وإن كان يتقاضاه طبعه أن يغوص في البحار ويُخرج دررَها وجواهرَها، ولكن لا ينبغي أن تغرَّه نفاسةُ جواهرها مع عجزه عن نَيلها، بل ينبغي أن ينظر إلى عجزه وكثرة معاطبها ومهالكها،\rويتفكر أنه إن فات نفائس البحر .. فما فاته إلا زيادات وتوسعات في المعيشة وهو مستغنٍ عنها، وإن غرق أو التقمه تمساح .. فاته أصل الحياة 1.\rفإن قلت: إن لم ينصرف قلبه من التفكر والتشوف إلى البحث فما طريقه؟ قلت: طريقه أن يُشْغِلَ نفسه بعبادة الله وبالصلاة\r_______________\r(1) فيه أن العلوم الناشئة عن قراءة هذه الآيات والأخبار إنما هي خصيصة للعارفين برب العالمين، لم يكلف المولى عامة المؤمنين من عباده بدركها، وهو الذي قد يعنيه الإمام في الإحياء (366/ 1) بقوله: (إفشاء سر الربوبية كفر)."], [89, "وقراءة القرآن والذكر، فإن لم يقدر .. فبعلم آخر لا يناسب هذا الجنس،\rمن لغة أو نحو، أو حساب أو طب، أو فقه، فإن لم يمكنه .. فبحِرفةٍ وصناعة ولو الحراثة والحيَّاكة، فإن لم يقدر ..\rفبلعب ولهو، فإن لم يقدر .. فيحدِّث نفسه بهول القيامة والحشر والنشر والحساب.\rوكل ذلك خير له من الخوض في هذا البحر البعيدِ غورُه وعمقُه، العظيمِ خطرُه وضررُه.\rبل لو اشتغل العامي بالمعاصي البدنية .. ربما كان أسلم له من أن يخوض في البحث عن معرفة الله تعالى؛ فإن ذلك عاقبتُه\rالفسق، وهذا عاقبتُه الشرك، {إِنَّ اللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَن يَشَاءُ} 1 [النساء: 116].\rفإن قلت: العامي إذا لم تكن نفسه إلى الاعتقادات الدينية إلا بدليل .. فهل يجوز أن يكون له الدليل؟ فإن جوزتَ ذلك ..\rفقد رخصتَ له في التفكر والنظر، وأي فرق بين هذا النظر وبين غيره؟ وإن منعت .. فكيف تمنعه ولا يتم إيمانه الا به؟\r_________________\r(1) قال الإمام الغزالي رحمه الله تعالى في «الإحياء (578/ 5): (والعاميُّ يفرح بالخوض في العلم؛ إذ الشيطان يخيل إليه: أنك من العلماء وأهل الفضل، ولا يزال يحبِّبُ إليه ذلك حتى يتكلَّم في العلم بما هو كفر وهو لا يدري، وكل كبيرة يرتكبها العاميُّ فهي أسلم له من أن يتكلَّم في العلم، لا سيما فيما يتعلق بالله وصفاته ... )، وليس المراد هنا: تقرير ارتکاب المعاصي، بل المراد: تبين أخف الضررين."], [90, "والجواب: أني أجوِّز له أن يسمع الدليل على معرفة الخالق ووحدانيته، وعلى صدق الرسول صلى الله عليه وسلم، وعلى اليوم الآخر، ولكن بشرطين:\rأحدهما: أن لا يزاد معه على الأدلة التي في القرآن.\rوالآخر: أن لا يماري فيه إلا مراءً ظاهراً 1، ولا يتفكر فيه إلا تفكُراً سهلاً جلياً، ولا يمعن في التفكر، ولا يوغل غاية الإيغال في البحث.\rوأدلة هذه الأمور الأربعة: ما ذكر في القرآن.\rأما الدليل على معرفة الخالق .. مثل قوله تعالى: {قُلْ مَن يَرْزُقُكُم مِّنَ السَّمَاءِ وَالْأَرْضِ أَمَّن يَمْلِكُ السَّمْعَ وَالْأَبْصَارَ وَمَن يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَن يُدَبِّرُ الْأَمْرَ فَسَيَقُولُونَ اللَّهُ} [يونس: 31].\rوقوله: {أَفَلَمْ يَنظُرُوا إِلَى السَّمَاءِ فَوْقَهُمْ كَيْفَ بَنَيْنَاهَا وَزَيَّنَّاهَا وَمَا لَهَا مِن فُرُوجٍ. وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ بَهِيجٍ. تَبْصِرَةً وذكرى لِكُلِّ عَبْدٍ مُّنِيبٍ. وَنَزَّلْنَا مِنَ السَّمَاءِ مَاءً مُّبَارَكًا فَأَنبَتْنَا بِهِ جَنَّاتٍ وَحَبَّ الْحَصِيدِ. وَالنَّخْلَ بَاسِقَاتٍ لَّهَا طَلْعٌ نَّضِيدٌ. رِزْقًا لِلْعِبَادِ} [ق: 6 - 11].\r_______________\r1) المراء الظاهر: الجدال بطيب الكلام السهل الواضح القريب المأخذ من ذهن العامة."], [91, "وكقوله: {فَلْيَنْظُرِ الْإِنْسَانُ إِلَى طَعَامِهِ. أَنَّا صَبَبْنَا الْمَاءَ صَبًّا ... الى قوله {مَتَاعًا لَكُمْ وَلِأَنْعَامِكُمْ} [عبس: 32]،\rوقوله تعالى: {أَلَمْ نَجْعَلِ الْأَرْضَ مِهَادًا. وَالْجِبَالَ أَوْتَادًا ... } إلى قوله: {وَجَنَّاتٍ أَلْفَافًا} [النبأ: 6 - 16].\rوأمثال ذلك, هو قريب من خمسمائة آية، جمعناها في كتاب (جواهر القرآن) (1)، به ينبغي أن يعرفَ الخلقُ جلالَ الله الخالقِ وعظمتَه، لا بقول المتكلِّمين: (إنَّ الأعراض حادثة، وإنَّ الجواهر لا تخلو عن الأعراض الحادثة، وما لا يخلو عن الأعراض الحادثة فهي حادثٌ، ثم الحادث يفتقر إلى محدث)\rفإن تلك التقسيمات والمقدمات وإثباتها بأدلتها الرسمية .. تشوش قلوب العوام، والدلالات الظاهرة القريبة من الأفهام على ما في القرآن .. تُقنعُهم وتسكِّن نفوسهم، وتغرس في قلوبهم الاعتقادات الجازمة (2).\r\rوأما الدليل على الوحدانية .. فيقنع فيه بما في القرآن؛ من قوله تعالى: {لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا} [الأنبياء: 22]، فإن اجتماعَ المُدَبِّرين سببُ إفسادِ التدبير.\r______________________\r(1) انظر \"جواهر القرآن\" (ص 86 - 146)، فإحالة المؤلف على كتابه \"جواهر القرآن\" بالغة الأهمية؛ لأنه جمع المتفرق في علم الكلام كجمع من جمع آيات الأحكام؛ إذ ذكر فيه رأيه من علم الكلام، وذکر کتبه الكلامية التي ألفها فيه.\r(2) وهذا هو الفرق بين غرس العقيدة للعوام، ودرس العقيدة للعلماء؛ فلكل مقام مقال."], [92, "وبمثل قوله تعالى: {لَّوْ كَانَ مَعَهُ آلِهَةٌ كَمَا يَقُولُونَ إِذًا لَّابْتَغَوْا إِلَى ذِي الْعَرْشِ سَبِيلًا} [الإسراء: 42].\rوقوله تعالى: {مَا اتَّخَذَ اللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُ مِنْ إِلَهٍ إِذًا لَّذَهَبَ كُلُّ إله بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ على بَعْضٍ} [المؤمنون: 91].\rوأما صدق الرسول صلى الله عليه وسلم .. فيستدل عليه بقوله تعالى: {قُل لَّئِنِ اجْتَمَعَتِ الْإِنسُ وَالْجِنُّ عَلَى أَن يَأْتُوا بِمِثْلِ هَذَا الْقُرْآنِ لَا يَأْتُونَ بِمِثْلِهِ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا} [الإسراء: 88]،\rوبقوله: {فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِ} [البقرة: 23]، وقوله: {قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِّثْلِهِ مُفْتَرَيَاتٍ} [هود: 13] وأمثاله.\rوأما اليوم الآخر: فيستدل عليه بقوله تعالى: {قَالَ مَن يُحْيِي الْعِظَامَ وَهِيَ رَمِيمٌ. قُلْ يُحْيِيهَا الَّذِي أَنشَأَهَا أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ} [يس: 78 - 79]،\rوبقوله: {أَيَحْسَبُ الْإِنسَانُ أَن يُتْرَكَ سُدًى. أَلَمْ يَكُ نُطْفَةً مِّن مَّنِيٍّ يُمْنَى} إلى قوله تعالى: {أَلَيْسَ ذَلِكَ بِقَادِرٍ على أَن يُحْيِيَ الْمَوْتَى} [القيامة: 36 - 40]،\rوبقوله: {يَا أَيُّهَا النَّاسُ إِن كُنتُمْ فِي رَيْبٍ مِّنَ الْبَعْثِ فَإِنَّا خَلَقْنَاكُم مِّن تُرَابٍ} إلى قوله: {{قَدِيرٌ} [الحج:5 - 6]"], [93, "وأمثال ذلك كثير في القرآن، فلا ينبغي أن يُزاد عليه.\rفإن قيل: فهذه الأدلة التي اعتمدها المتكلمون وقرروا وجه دلالتها، فما بالهم يمنعون عن غير هذه الأدلة ولا يمتنعون عنها، وكل ذلك مُدْرَكٌ بنظر العقل وتأمله؟!\rفإن فُتِح للعامي باب النظر .. فليُفتح مطلقاً أو ليُسَدَّ عليه طريق النظر رأساً، وليُكلَّفِ التقليد من غير دليل!!\rفالجواب: إن الدلالة تنقسم إلى ما يُحتاج فيه إلى تفكر وتدقيق خارجٍ عن طاقة العامِّيِّ وقدرته، وإلى ما هو جليٌّ سابق إلى الأفهام ببادئ الرأي وأوَّل النظر، كافَّة الناسِ في دركه.\rفما يدركه كافة الناس بسهولة .. فهذا لا خطر فيه، وما يفتقر إلى التدقيق .. فليس على حد وسعه، فأدلة القرآن مثل الغذاء ينتفعُ به كل إنسان، وأدلَّةُ المتكلمين: مثل الدواء ينتفع به آحاد الناس ويستضرُّ به الأكثرون، بل أدلة القرآن كالماء الذي ينتفع به الصبي الرضيع والرجل القويُّ، وسائر الأدلة كالأطعمة التي ينتفع بها الأقوياء مرةً ويمرضون بها أخرى، ولا ينتفع بها الصبيان أصلاً.\rولهذا قلنا: أدلة القرآن أيضاً ينبغي أن يصغى إليها إصغاء إلى كلام جلي ولا يمارى فيه إلا مراءً ظاهراً، ولا يكلف نفسه تدقيق الفكر وتحقيق النظر."], [94, "فمن الجلي: أنَّ من قدر على الابتداء .. فهو على الإعادة أقدر، كما قال: {وَهُوَ الَّذِي يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ وَهُوَ أَهْوَنُ عَلَيْهِ} [الروم: 27]، وأن التدبير لا ينتظم في دار واحدة بمدبِّرَين، فكيف ينتظم في كل العالم؟ وأن من خلق علم كما قال تعالى: {أَلَا يَعْلَمُ مَنْ خَلَقَ} [الملك: 14]. فهذه الأدلة تجري للعوام مجرى الماء الذي جعل الله منه كل شيء حي، وما أخذه المتكلمون وراء ذلك من تنقير وسؤال وتوجيه إشكال ثم اشتغال بحله فهو بدعة، وضرره في حق أكثر الخلق ظاهر، فهو الذي ينبغي أن يُتوقى. والدليل على تضرر الخلق به المشاهدة والعيان والتجربة، وما ثار من الشر منذ نبغ المتكلمون وفشت صناعة الكلام مع سلامة العصر الأول من الصحابة عن مثل ذلك، ويدل عليه أيضاً أن رسول الله صلى الله عليه وسلم والصحابةَ بأجمعهم ما سلكوا في المحاجة مسلك المتكلمين في تقسيماتهم و تدقيقاتهم، لا لعجز منهم عن ذلك، فلو علموا أن ذلك نافعٌ لأطنبوا فيه، ولخاضوا في تحرير الأدلة خوضاً يزيد على خوضهم في مسائل الفرائض."], [95, "فإن قيل: إنما أمسكوا عنه لقلة الحاجة، فإن البدع إنما نبغت بعدَهم فعظم حاجةُ المتأخرين، وعلم الكلام راجعٌ إلى علم معالجة المرضى بالبدع، فلما قَلَّتْ فى زمانهم أمراض البدع قلت عنايتهم بجميع طرق المعالجة، فالجواب من وجهين:\rأحدهما: أنهم في مسائل الفرائض ما اقتصروا على بيان حكم الوقائع، بل وضعوا المسائل وفرضوا فيها ما تنقضي الدهور ولا يقع مثله، لأن ذلك مما أمكن وقوعه، فصفوا علمه ورتبوه قبل وقوعه، إذ علموا أنه لا ضرر في الخوض فيه وفي بيان حكم الواقعة قبل وقوعها، والعناية بإزالة البدع ونزعها عن القوس أهم، فلم يتخذوا ذلك صناعةً لأنهم عرفوا أن الاستضرار بالخوض فيه أكثرُ من الانتفاع، ولولا أنهم كانوا قد حُذروا من ذلك وفَهموا تحريم الخوض فيه.\rوالجواب الثاني: أنهم كانوا محتاجين إلى محاجة اليهود والنصارى في إثبات نبوة محمد صلى الله عليه وسلم، وإلى إثبات البعث مع منكريه، ثم ما زادوا في هذه القواعد التي هي أمهات العقائد على أدلة القرآن، فمن أقنعه ذلك قبلوه، ومن لم يقنع قتلوه، وعدلوا إلى السيف والسنان بعد إفشاء أدلة القرآن، وما ركبوا ظهر اللجاج"], [96, "في وضع المقاييس العقلية (1) وترتيب المقدمات وتحريم طريق المجادلة وتذليل طرقها ومنهاجها، كل ذلك لعلمهم بأن ذلك مثار الفتن ومنبع التشويش، ومن لا يقنعه أدلة القرآن لا يقمعه إلا السيف والسنان، فما بعد بيان الله بيان.\rعلى أننا ننصف ولا ننكر أن حاجة المعالجة تزيد بزيادة المرض، وأن لطول الزمان وبُعد العهد عن عصر النبوة تأثيراً في إثارة الإشكالات (2)، وأن للعلاج طريقين:\rأحدهما: الخوض فى البيان والبرهان إلى أن يَصلح واحدٌ يفسد به اثنان، فإن صلاحه بالإضافة إلى الأكياس وفساده بالإضافة إلى البُلَهِ، وما أقل الأكياس وما أكثر البله! والعناية بالأكثرين أولى (3).\rالطريق الثاني: طريق السلف في الكف والسكوت والعدول\r____________\r1) اللجاج: التمادي في الخصومة.\r2) قال الإمام الغزالي رحمه الله تعالى في \"الإحياء\" (1\\ 291): (انما فضل الصحابة؛ لمشاهدتهم قرائن أحوال رسول الله صلى الله عليه وسلم، واعتلاق قلوبهم امورا أدركت بالقرائن، فسددهم ذلك الى الصواب من حيث لا يدخل في الرواية والعبارة؛ اذ فاض عليهم من نور النبوة ما يحرسهم في الأكثر عن الخطأ).\r3) فيكون الامر كما يفهم من كلام الإمام الغزالي رحمه الله تعالى في \"فيصل التفرقة\" (ص 97 - 98) بأن علم الكلام لأحد شخصين: صاحب شبهة لا تزول بالكلام الوعظي والقريب، وشخص كامل العقل راسخ في الدين يتعلمه لصون العقائد من المبتدعين وأهل الزيغ والضلال، وهذان قليل بالنسبة للجمهور؛ فعليه: لا ينبغي ذكره الا في المجالس الخاصة بأحد هذين الشخسين."], [97, "إلى الدرة والسوط والسيف، وذلك مما يقنع الأكثرين وإن كان لا يقنع الأقلين، وآية إقناعه أن من يسترق من الكفار من العبيد والإماء تراهم يُسلمون تحت ظلال السيوف ثم يستمرون عليه، حتى يصير طوعاً ما كان في البداية كرهاً، ويصير اعتقاداً جزماً ما كان في الابتداء مراءً وشكاً، وذلك بمشاهدة أهل الدين والمؤانسة بهم، وسماع كلام الله ورؤية الصالحين وخبرهم، وقرائن من هذا الجنس تناسب طباعهم مناسبةً أشد من مناسبة الجدل والدليل، فإذا كان كل واحد من العلاجَين يناسب قوماً دون قوم، وجب ترجيح الأنفع في الأكثر، فالمعاصرون للطبيب الأول المؤيد بروح القدس المكاشَف من الحضرة الإلهية الموحى إليه من الخبير البصير بأسرار عباده وبواطنهم أعرف بالأصوب والأصلح قطعاً، فسلوك سبيلهم لا محالة أولى."], [98, "الوظيفة السابعة: التسليم لأهل المعرفة\rوبيان أنه يجب على العامي أن يعتقد أن ما انطوى عنه من معاني هذه الظواهر وأسرارها ليس منطوياً عن رسول الله صلى الله عليه وسلم، وعن الصديق، وعن أكابر الصحابة، وعن الأولياء والعلماء الراسخين، وأنه إنما انطوى عنه لعجزه وقصور معرفته، فلا ينبغي أن يقيس بنفسه غيرَه، فلا تُقاس الملائكة بالحدادين (1).\rوليس ما يخلو عنه مَخادعُ العجائز يلزم منه أن يخلو عنه خزائنُ الملوك (2)، فقد خُلق الناس أشتاتاً متفاوتين كمعادن الذهب والفضة وسائر الجواهر، فانظر إلى تفاوتها وتباعد ما بينهما صورةً ولوناً وخاصيةً ونفاسةً، فكذلك القلوب معادن لسائر جواهر المعارف، فبعضها معدن النبوة والولاية والعمل ومعرفة الله تعالى، وبعضها معدن للشهوات البهيمية والأخلاق الشيطانية.\r______________\r(1) مثل جرى على الألسنة، وسببه: لما نزل قول تعالى: {عَلَيْهَا تِسْعَةَ عَشَرَ} .. قال أبو جهل لقريش: ثكلتكم امهاتكم؛ محمد يقول: إن خزنة النار تسعة عشر وأنتم الجمع العظيم؛ أيعجز كل عشرة منكم أن يبطشوا برجل منهم؟! فقال أبو الأشد بن أسيد الجمحي - وكان شديد البطش -: أنا اكفيكم سبعة عشر, وأكفوني أنتم اثنين! فقال الصحابة عندئذ: (ويحكم؛ لا تقاس الملائكة بالحدّادين!) فجرى هذا مثلا في كل شيئين لا مقارنة بينهما. والحدّاد: هو السجّان للنار في دكّانه ومحلّه؛ فلا يقاس هذا الحداد بالملائكة خزنة جهنم؛ فالبون بينهما شاسع، ولا وجه للمقارنة أصلا؟!\r(2) المخادع - جمع مخدع بضم الميم وكسرها -: الخزانة."], [99, "بل ترى الناس يتفاوتون في الحِرَفِ والصناعات، فقد يقدر الواحد بخفة يده وحذاقة صناعته على أمور لا يطمع الآخر في بلوغ أوائله فضلاً عن غايته، ولو اشتغل بتعلمه جميع عمره، فكذلك معرفة الله تعالى، بل كما ينقسم الناس إلى جَبَانٍ عاجز لا يطيق النظر إلى التطام أمواج البحر وإن كان على ساحله، وإلى من يطيق ذلك لكن لا يطيق رفع الرجل عن الأرض اعتماداً على السباحة، وإلى من يطيق السباحة إلى حد قريب من الشط لكن لا يمكنه الخوض في أطرافه وإن كان قائماً في الماء على رجله، وإلى من يطيق ذلك لكن لا يطيق خوض البحر إلى لجته والمواضع المغرقة المخطرة، وإلى من يطيق ذلك لكن لا يطيق الغوص في عمق البحر إلى مستقره الذي فيه نفائسه وجوهره، فهكذا مثال بحر المعرفة وتفاوت الناس فيه مثله حذو القذة بالقذة من غير فرق (1).\rفإن قيل: فالعارفون يحيطون بكمال معرفة الله تعالى؛ حتى لا ينطوي عنهم شيء؟\rقلنا: هيهات! فقد بيَّنا بالبرهان القطعي في كتاب \"المقصد الأسنى في معاني أسماء الله الحسنى\" أنه لا يعرف اللهَ كنه معرفته إلا الله تعالى، وأن الخلائق وإن اتسعت معرفتهم وغزُرَ\r________________\r(1) القُذَّة: الواحدة من ريش السهم، وهو مثل يضرب للشيئين يستويان ولا يتفاوتان."], [100, "علمهم، فإذا أضيف ذلك إلى علم الله سبحانه فما أوتوا من العلم إلا قليلاً (1).\rلكن ينبغي أن يعلم أن الحضرة الإلهية محيطة بكل ما في الوجود؛ إذ ليس في الوجود إلا الله تعالى وأفعاله، فالكل من الحضرة الإلهية؛ كما أن جميع أرباب الولايات في المعسكر من الحراس وغيرهم .. من جملة الحضرة السلطانية.\rوأنت لا تفهم الحضرة الإلهية إلا بالتمثيل إلى الحضرة السلطانية؛ فاعلم أن كل ما في الوجود داخل في الحضرة الإلهية (2)، ولكن كما أن السلطان له في مملكته قصر خاص، وفي فِناءِ قصره ميدان واسع، ولذلك الميدان عتبة يجتمع عليها جميع الرعايا، ولا يمكَّنون من مجاوزة العتبة ولا إلى طرف الميدان، ثم يُؤذَنُ لخواص المملكة في مجاوزة العتبة ودخول الميدان والجلوس فيه، على تفاوتٍ في القرب والبعد بحسب مناصبِهِم، وربما لم يطرقْ إلى القصرِ الخاصِّ إلا الوزير وحده، ثم إن الملك يُطلِعُ الوزير من أسرار ملكِهِ على ما يريد، ويستأثر عنه بأمور لا يُطلِعُهُ عليها .. فكذلك فافهم على هذا المثال تفاوتَ الخلق في القرب من الحضرة الإلهية.\r_________________\r(1) يقول العارف بالله تعالى الشيخ علي بن الهيتي رحمه الله تعالى: (الحق تعالى وراء كلِّ ما أدركه الخلق بأفهامهم، أو أحاطوا به بعلومهم، وأشرفوا عليه بمعارفهم) انظر \"طبقات الشعراني\" (1/ 145).\r(2) في (ب، ه): (المملكة الإلهية)."], [101, "فالعتبة التي هي آخر الميدان موقفُ العوام ومردهم، لا سبيل لهم إلى مجاوزتها، فإن جاوزوا حدهم استوجبوا الزجر والتنكيل، وأما العارفون فقد جاوزوا العتبة وانسرحوا في الميدان، ولهم فيه جولان على حدود مختلفة في القرب والبعد وتفاوت ما بينهم كثير، وإن اشتركوا في مجاوزة العتبة وتقدموا على العوام المفترشين، وأما حظيرة القدس في صدر الميدان فهي أعلى من أن يطأها أقدام العارفين وأرفع من أن يمتد إليها أبصار الناظرين، بل لا يلمح ذلك الجنابَ الرفيعَ صغيرٌ وكبيرٌ إلا غض من الدهشة والحيرة طرفُه فانقلب إليه البصر خاسئاً وهو حسير.\rفهذا ما يجب على العامي أن يؤمن به جملة وإن لم يُحِطْ به تفصيلاً، فهذه الوظائف السبع الواجبة على عوام الخلق في هذه الأخبار التي سألتَ عنها حقيقةُ مذهب السلف، وأما الآن فنشغل بإقامة الدليل على أن الحق هو مذهب السلف."], [105, "الباب الثاني\rفي إقامة البرهان على أن الحق مذهب السلف\r"]], "pg": [88, 105]}, "448.16": {"x": [[105, "وعليه برهانان: عقلي وسمعي.\rأما العقلي .. ففنّان: كلي وتفصيلي.\r****\rأما البرهان الكلي على أن الحق مذهبُ السلف .. فينكشف بتسليم أربعة أصول هي مسلَّمة عند كل عاقل:\rالأول: أَنَّ أعرفَ الخلق بصلاح أحوال العباد بالإضافة إلى حسن المعاد .. هو النبي صلى الله عليه وسلم؛ فإنّ ما يَنفع في الآخرة أو يضرُّ لا سبيل إلى معرفته بالتجربة كما عُرِفَ الطبُّ، إذ لا مجال للعلوم التجريبية (1) إلا بما يُشاهد على سبيل التكرُّرِ، وَمَنِ الذي رجع من ذلك العالَم فأدرك بالمشاهدة ما نفع وضر وأخبر عنه؟!\rولا يُدرك بقياس العقل، فإن العقولَ قاصرةٌ عن ذلك، والعقلاءُ بأجمعهم معترفون بأن العقل لا يهتدي إلى ما بعد الموت، ولا يرشد إلى وجه ضرر المعاصي ونفع الطاعات، لا سيما على سبيل التفصيل والتحديد كما وردت به الشرائع، بل أقروا بجملتهم أن\r_______________\r(1) في (ه) وحدها: (التجريبية)."], [106, "ذلك لا يدرَك إلا بنور النبوة (1)، وهي قوة وراء العقل يدرَك بها من أمر الغيب في الماضي والمستقبل أمورٌ لا على طريق التعرف بالأسباب العقلية.\rوهذا مما اتفق عليه الأوائل من الحكماء فضلاً عن الأولياء والعلماء والراسخين القاصرين نظرَهم على الاقتباس من حضرة النبوة، المقربين بقصور كل قوة سوى هذه القوة.\r***\rالأصل الثاني: أنه صلى الله عليه وسلم أفاض إلى الخلق ما أوحى إليه من صلاح العباد في معادهم ومعاشهم، وأنه ما كتم شيئاً من الوحي ولا أخفاه ولا طواه عن الخلق، فإنه لم يُبعث إلا لذلك، ولذلك كان رحمةً للعالمين، فلم يكن متهما فيه.\rوعُرف ذلك علماً ضرورياً من قرائن أحواله في حرصه على إصلاح الخلق، وشغفه بإرشادهم إلى صلاح معاشهم ومعادهم، فما ترك شيئاً مما يُقَرِّبُ الخلق إلى الجنة ورضا الخالق .. إلا دلهم عليه وأمرهم به وحثهم عليه، ولا شيئاً مما يقرِّبهم إلى النار وإلى سخط الله تعالى .. إلا حذرهم منه ونهاهم عنه، وذلك في العلم والعمل جميعاً.\r****\r_______________\r(1) فإن القائلين بحاكمية العقل في التحسين والتقبيح ولزوم الثواب والعقاب .. مقرُّون بعجز العقل عن مقادير هذا الجزاء، ففي كلامه تنزُّل رحمه الله تعالى."], [107, "الأصل الثالث: أنّ أعرف الناس بمعاني كلامه عليه السلام وأحراهم بالوقوف على كنهه ودرك أسراره .. الذين شاهدوا الوحي والتنزيل, وعاصروه وصاحبوه، بل لازموه آناء الليل واطراف النهار، مشمرين لفهم معاني كلامه وتلقيه بالقبول للعمل به أولاً، وللنقل إلى من بعدهم ثانياً، وللتقرب إلى الله سبحانه بسماعه وفهمه, وحفظه ونشره، وهم الذين حثهم رسول الله صلى الله عليه وسلم على السماع والفهم والحفظ والأداء، فقال: (نَضَّرَ الله امرأً سَمِعَ مقالتي فوعاها، فأدَّاها كما سمعها .. ) الحديث (1).\rفليت شعري!! أَيُتَّهَمُ رسولُ الله صلى الله عليه وسلم بإخفائه وكتمانه عنهم؟! حاشا منصب النبوة عن ذلك، أم يتهم أولئك الأكابر في فهم كلامه وإدراك مقاصده؟! أو يُتهمون في إخفائه وستره بعد الفهم؟! أو يتهمون في معاندته من حيث العمل ومخالفته على سبيل المكابرة مع الاعتراف بتفهيمه وتكليفه؟! فهذه الأمور لا يتسع لتقديرها عقل عاقلٍ.\r***\rالأصل الرابع: أنهم في طول عصرهم إلى آخر أعمارهم ما دعوا الخلقَ إلى البحث والتفتيش والتفسير والتأويل والتعرض\r_________________\r(1) رواه أبو داود (3652)، والترمذي (2656)، والنسائي في \"الكبرى\" (5816)، وابن ماجه (241) عن سيدنا زيد بن ثابت رضي الله عنه."], [108, "لمثل هذه الأمور، بل بالغوا في زجر من خاض فيه وسأل عنه وتكلّم به (1)، على ما سنحكيه عنهم (2).\rفلو كان ذلك من الدين، أو كان من مدارك علم الدين .. لأقبلوا عليه ليلاً ونهاراً، ودعوا إليه أولادهم وأهليهم، وتشمروا عن ساق الجد في تأسيس أصوله وشرح قوانينه تشميراً أبلغ من تشميرهم في تمهيد قواعد الفرائض والمواريث.\rفيعلم بالضرورة من هذه الأصول أن الحق ما قالوه، والصواب ما أرادوه، لا سيّما وقد أثنى عليهم رسول الله صلى الله عليه وسلم فقال: (خير الناس قرني، ثم الذين يلُونهم، ثم الذين يلونهم) (3).\rوقال صلى الله عليه وسلم: (ستفترق أمتي نَيِّفاً وسبعين فرقةً، الناجيةُ منهم واحدة)، فقيل: من هم؟ فقال: (أهل السنة والجماعة)، فقيل: (ما أنا عليه الآن وأصحابي) (4).\rالبرهان الثاني: هو التفصيلي, فنقول: ادَّعينا أن الحق هو\r________________\r(1) انظر خبر سيدنا عمر رضي الله عنه مع صبيغ (ص 64).\r(2) سيأتي (ص 114).\r(3) رواه البخاري (2652)، ومسلم (2533) عن سيدنا عبد الله بن مسعود رضي الله عنه.\r(4) رواه بنحوه أبو داوود (4587) عن سيدنا معاوية رضي الله عنه، والترمذي (2641) عن سيدنا عبد الله بن عمرو رضي الله عنهما، وابن ماجه (4149) عن سيدنا عوف بن مالك رضي الله عنه، وانظر «إتحاف السادة المتقين» (8/ 140 - 141)."], [109, "مذهب السلف، وأن مذهب السلف هو توظيف الوظائف السبع على عوام الخلق في ظواهر الأخبار المتشابهة، وقد ذكرنا برهان كل وظيفة معها؛ فهو برهان كونه حقاً.\rفمن يخالف - ليت شعري - أيخالف في قولنا الأول: أنه يجب على العامي التقديس للحق عن التشبيه ومشابهة الأجسام؟!\rأو في قولنا الثاني: أنه يجب عليه التصديق والإيمان بما قاله الرسول صلى الله عليه وسلم بالمعنى الذي أراده؟!\rأو في قولنا الثالث: إنه يجب عليه الاعتراف بالعجز عن درك حقيقة تلك المعاني؟!\rأو في قولنا الرابع: إنه يجب عليه السكوت عن السؤال، والخوضُ فيما هو وراء طاقته؟!\rأو في قولنا الخامس: إنه يجب عليه إمساك اللسان عن تغيير الظواهر بالزيادة والنقصان والجمع التفريق؟!\rأو في قولنا السادس: إنه يجب عليه كف القلب عن الفكر فيه مع عجزه عنه، وقد قيل لهم: تفكروا في الخلق الله، ولا تفكروا في ذات الله\"؟! (1)\r____________________\r(1) رواه أبو الشيخ في العظمة، (2) عن سيدنا ابن عباس رضي الله عنهما، وأبو نعيم في الحلية، (66/ 6) عن سيدنا عبد الله بن سلام رضي الله عنه، والخطيب في تاريخه (147/ 18) عن سيدنا أبي هريرة رضي الله عنه، وانظر «کشف الخفاء، (311/ 1)، والمقاصد الحسنة (342)"]], "pg": [105, 109]}, "448.17": {"x": [[110, "أو في قولنا السابع: إنه يجب عليه التسليم لأهل المعرفة من الأنبياء والأولياء والعلماء الراسخين؟!\rفهذه أمور بيناها وبرهناها (1)، ولا يقدر أحد على جحدها وإنكارها إن كان من أهل التمييز فضلاً عن العلماء والعقلاء.\rفهذه هي البراهين العقلية.\r********\rالنمط الثاني: البرهان السمعي على ذلك.\rوطريقه أن نقول: الدليل على أن الحق مذهب السلف: أنّ نقيضَه بدعةٌ, والبدعة مذمومة وضلالة، والخوض من جهة العوام في التأويل، والخوض بهم فيه من جهة العلماء .. بدعة، وكان نقيضه وهو الكف عن ذلك ... سنة محمودة.\rفها هنا ثلاثة أصول:\rأحدها: أن البحث والتفتيش والسؤال عن هذه الأمور .. بدعة.\rوالثاني: أن كل بدعة فهي مذمومة (2).\rوالثالث: أن البدعة إذا كانت مذمومة كان نقيضُها، وهي السنة القديمة، محموداً.\r__________________\r(?) في جميع النسخ عدا (ج): (فهذه أمور بيانها برهائها).\r(?) جعل الإمام الغزالي رحمه الله تعالى هنا القضية کلية .. خاص بالبدعة المذمومة في الدين كما ستتبن."], [111, "ولا يمكن النزاع في شيء من هذه الأصول، وإذا سلِّمت .. انتجت أن الحق مذهب السلف.\r******\rفإن قيل: بِمَ تُنكرون على من يمنع كون البدعة مذمومةً, أو يمنع كون البحث والتفتيش بدعةً, فينازع في الأصلين الأولين ولا ينازع في الثالث لظهوره؟\rفنقول: الدليل على إثبات الأصل الأول من كون البدعة مذمومةً: اتفاقُ الأمة قاطبة على ذم البدعة وزجر المبتدع وتعييب من يُعرف بالبدعة، وهذا مفهومٌ على الضرورة من الشرع، وذلك غير واقع في محل الظن (1).\rفَذَمُّ رسول الله صلى الله عليه وسلم البدعةَ عُلِمَ بالتواتر بمجموع أخبار يفيد العلمَ القطعيَّ جملتُها، وإن كان الاحتمال\rيتطرق إلى آحادها؛ وذلك كعلمنا بشجاعة علي رضي الله عنه، وسخاوة حاتم، وحب رسول الله صلى الله عليه وسلم لعائشة رضي الله عنها، وما جري مجراها؛ فإنه عُلِمَ قطعاً بأخبار آحاد بلغت في الكثرة مبلغاً لا تحتمل كذبَ ناقليها، وإن لم تكن آحادُ تلك الأخبار متواترةً (2).\r__________________\r(1) يعني: بعد الاتفاق على بدعية أمر ما .. لا خلاف في ذمه، وإنما خلاف الفرقاء عند التباحث في كونه بدعة أو أنه ليس ببدعة. (?) وهو المسمى بالتواتر المعنوي، لا اللفظي. انظر «فتح المغ?ث» (??/4)."], [112, "وذلك مثل ما روي عن رسول الله صلى الله عليه وسلم أنه قال: (عليكم بسنتي وسنة الخلفاء الراشدين المهديين من بعدي، عضوا عليها بالنواجذ، وإياكم ومحدثات الأمور، فإن كل محدثة بدعة (1) وكل بدعة ضلالة، وكل ضلالة في النار) (2)\rوقال صلى الله عليه وسلم: (اتبعوا ولا تبتدعوا، وإنما هلك من كان قبلكم لمّا ابتدعوا في دينهم وتركوا سُنَنَ أنبيائهم وقالوا بآرائهم فضلُّوا وأضلُّوا) (3)\rوقال صلى الله عليه وسلم: (إذا مات صاحب بدعة ... فقد فُتح على الإسلام فتحٌ) (4)\rوقال صلى الله عليه وسلم: (من مشى إلى صاحب بدعة ليوقرَه .. فقد أعان على هدم الإسلام) (5).\rوقال صلى الله عليه وسلم: (من أعرض عن صاحب بدعة بُغْضاً له في الله تعالى .. ملأ الله قلبه أمناً وإيماناً، ومن انتهر صاحبَ بدعة .. رفع الله تعالى له مائة درجة، ومن\r_________________\r(1) كذا في جميع النسخ، والرواية: \"محدثة\"، بدل \"محدث\".\r(2) رواه بنحوه أبو داوود (4599)، والترمذي (2676)، وابن ماجه (44) عن سيدنا العرباض بن سارية رضي الله عنه.\r(3) قوله: \"اتبعوا ولا تبتدعوا\" رواه الدارمي في \"مسنده\" (211)، والبيهقي في \"الشعب\" (2024) موقوفا على سيدنا عبد الله بن مسعود رضي الله عنه، وباقيه أورده بنحوه ابن عبد البر في \"جامع بيان العلم وفضله\" (2026) من كلام الشعبي رحمه الله تعالى.\r(4) رواه الخطيب في \"تاريخ بغداد\" (380/ 4)، وهو عند الديلمي في \"الفردوس\" (1118) عن سيدنا أنس رضي الله عنه.\r(5) رواه الطبراني في \"الكبير\" (20/ 96) عن سيدنا معاذ بن جبل رضي الله عنه."], [113, "سلم على صاحب بدعة, أو لقيه بالبشرى, أو استقبله بما يسرُّه .. فقد استخف بما أُنزل على محمد صلى الله عليه وسلم) (1).\rوقال صلى الله عليه وسلم: (إن الله لا يقبل لصاحب بدعة صوماً ولا صلاةً, ولا زكاةً ولا حجاً, ولا عمرةً ولا جهاداً, ولا صرفاً ولا عدلاً، ويَخرج من الإسلام كما يخرج السهم من الرمية, أو كما يخرج الشعرة من العجين) (2).\rفهذا وأمثاله مما يجاوز حد الحصر أفاد علماً ضرورياً بكون البدعة مذمومة.\r************\rفإن قيل: سلمنا أن البدعة مذمومة، ولكن ما دليل الأصل الثاني؛ وهو أن هذا بدعة, فإن البدعة عبارة عن كل محدَث؟! قال الشافعي رضي الله عنه: الجماعة في التراويح بدعة؛ وهي بدعة حسنة؟! وخوض الفقهاء في تفاريع الفقه ومناظرتُهم فيها مع ما أبدعوه من نقص وكسر (3) , وفساد ووضع وتركيب (4) , وتعدية\r__________________\r(1) رواه أبو نعيم في \"الحلية\" (199/ 8) عن سيدنا عبد الله بن عمر رضي الله عنهما.\r(2) رواه ابن ماجه (51) عن سيدنا حذيفة رضي الله عنه.\r(3) النقض والكسر: مصطلحان أصوليان في هدم دليل المستدل؛ وذلك بإثبات صور وجدت فيها العلة ولم يوجد فيها الحكم. انظر \"التعريفات\" للجرجاني (ص 336).\r(4) فساد الوضع: هو عبارة عن كون العلة معتبرة في نقيض الحكم بالنص أو الإجماع؛ مثل تعليل أصحاب الشافعي لإيجاب الفرقة بسبب إسلام أحد الزوجين. انظر \"التعريفات\" (ص 245)."], [114, "وفنون مجادلة، وإلزام .. كل ذلك مُبْدَعٌ لم يُؤْثَرْ عن الصحابة شيءٌ من ذلك.\rفدل على أن البدعة المذمومة: ما رَفَعَتْ سُنَّةً مأثورة، ولا نُسَلِّمُ أن هذا رافعٌ لسنة مأثورة ثابتة، لكنه مُحْدَثٌ خاض فيه الأولونُ،\rإما لاشتغالهم بما هو أهم منه، وإما لسلامة القلوب في العصر الأول عن الشكوك والترددات، فاستغنوا عن الخوض فيه، وخاض فيه من بعدَهم لحدوث الأهواء والبدع, ومسيس الحاجة الى ابطالها، وإفحام منتحليها.\rالجواب: أن ما ذكرتموه من أن البدعة المذمومة كل محدث رفع سنة قديمة .. هو الحق، وهذه بدعة رفعت سنةً قديمةً، إذ كانت سنة الصحابة المنعَ من الخوض فيه، وزجرَ من سأل عنه، والمبالغةَ في تأديبه ومنعه, وفتحُ باب السؤال عن هذه المسائل، والخوضُ بالعوام في غمرة هذه المشكلات .. على خلاف ما تواتر عنهم.\rوقد صح ذلك عن الصحابة بتواتر النقل عند التابعين من نقلة الآثار وسيرِ السلف صحةً لا يتطرق إليها ريبٌ ولا شَكٌّ، كما تواتر خوضُهم في مسائل الفرائض ومشاورتهم في أحكام الوقائع الفقهية، وحصل العلم به أيضاً بأخبار آحاد لا يتطرق الشك إلى مجموعها، وإن تطرق الإحتمال إلى آحادها كما ذكرناه في ذم البدعة, كما نُقِلَ عن عمر رضي الله عنه أنه"], [115, "سَأَلَ سائلٌ عن آيتين متشابهتين فعلاه بالدِّرَّةِ (1).\rوكما روي أنه سأله سائلٌ عن القرآن: أهو مخلوق أم لا؟ قال أبو هريرة رضي الله عنه: (كنت جالساً عنده لمّا سئل عن ذلك وهو أمير المؤمنين يومئذ، فتعجب عمر رضي الله عنه من قوله، فأخذ بيده حتى جاء به إلى علي رضي الله عنه، فقال: يا أبا الحسن استمع ما يقول هذا الرجل!!\rقال: وما يقول يا أمير المؤمنين؟\rفقال الرجل: سألته عن القرآن أمخلوق هو أم لا؟\rفوجم لها رضي الله عنه، وطأطأ رأسه، ثم رفع رأسه وقال: سيكون لكلام هذا نبأ في آخر الزمان، ولو وليتُ من أمره ما وليت .. لضربتُ عنقَه.\rوقد روى أحمد بن حنبل هذا الحديث عن أبي هريرة (2).\rفهذا قول علي رضي الله عنه في هذا السائل بحضور عمر وأبي هريرة رضي الله عنهم، ولم يقولا له ولا أحدٌ ممن بلغه ذلك من الصحابة، ولا عرفه عليٌّ رضي الله عنه في\r___________________\r(1) انظر خبره تعليقا (ص 64).\r(2) رواه نصر بن إبراهيم المقدسي في «مختصر الحجة على تارك المحجة» (529)، ثم قال: (وهذا التشديد من الصحابة رضي الله عنهم، والمنع من الكلام في هذه المسائل وأشباهها وإن كانت جواباتها عندهم معلومة، وأحكامها مفهومة .. إرادة لحسم الباب وقطع السؤال؛ لئلا يؤدي إلى ما لا يؤمر به في الشريعة، ويتسع الأمر فيما يخالف ما أمر الله به ورسوله)، والوجم: السكوت على غيظ، وعبوس الوجه من شدة الحزن."], [116, "نفسه: إن هذا سؤال عن مسألة دينية، وَتَعَرُّفٌ لحكمِ كلامِ الله تعالى، وطلبُ معرفةٍ لصفة القرآن الذي هو معجزةٌ دالةٌ على صدق الرسول، بل هو الدليل المُعَرِّفُ لأحكام التكليف، فلم يستوجبْ طالبُ المعرفة هذا التشديد؟!\rفانظر إلى فراسة علي رضي الله عنه وإشرافه على أنّ ذلك قرعٌ لباب الفتنة، وأن ذلك سينتشرُ في آخر الزمان الذي هو موسم الفتن ومظنتُها بوعد رسول الله صلى الله عليه وسلم، وانظر إلى تشديده وقوله: ولو وليت من أمره ما وليت .. لضربت عنقه، فمثل أولئك السادة الأكابر الذين شاهدوا الوحيَ والتنزيلَ، واطلعوا على أسرار الدين وحقائقه، وقد قال صلى الله عليه وسلم في أحدهما: (لو لم أبعث .. لبعثت يا عمر) (1)، وقال في الثاني: (أنا مدينة العلم وعليٌّ بابها) (2) .. يزجرون السائل عن مثل هذا السؤال، ثم يزعم مَنْ بعدَهم من المشغوفين بالكلام والمجادلة، وممن لو أنفق ما في الأرض جميعاً ما بلغ مُدَّ أحدهم ولا نصيفه (3) .. أن الحق والصواب قبولُ هذا السؤال، والخوضُ\r_________________\r(1) رواه بنحوه أحمد في و فضائل الصحابة» (672) عن سيدنا عقبة بن عامر رضي الله عنه، وانظر، إتحاف السادة المتقين» (572/ 7).\r(2) رواه الحاكم في «المستدرك»، (3/ 126)، والطبراني في \"الكبير\"، (55/ 11) عن سيدنا عبد الله بن عباس رضي الله عنهما، وانظر «کشف الخفاء»، (1/ 203 - 205). (3) كما في الحديث الذي رواه البخاري (3673)، ومسلم (2541) عن سيدنا أبي سعيد الخدري رضي الله عنه."], [117, "في الجواب، وفتحُ هذا الباب، ثم يعتقدُ فيه أنه محق، وفي عمر وعلي رضي الله عنهما أنهما مبطلان!!\rهيهات! ما أبعد عن التحصيل وما أخلى عن الدين من قاس الملائكة بالحدادين (1)، بل رجح المجادلين على الأئمة الراشدين والسلف الصالحين!!\r********\rفإذاً؛ قد عُرِفَ على القطع أن هذه بدعةٌ مخالفةٌ لسنة السلف، لا كخوض الفقهاء في التفاريع والتفاصيل، فإن ذلك وإن كان محدثاً .. فليس مخالفاً سنّةَ السلف؛ فما نُقِلَ عنهم زجرٌ عن الخوض فيه، بل إمعانُهم في الخوض في مسائل الفرائض عرّف جواز الخوض (2).\rوأما ما أُبدع من فنون المجادلات .. فهي بدعةٌ مذمومةٌ عند أهل التحصيل, ذكرنا وجهَ ذمها في كتاب (قواعد العقائد) من كتب \"الإحياء علوم الدين\" (3)\r__________________\r(1) انظر (ص 98)\r(2) ومع هذا فقد حدَّ الإمام الغزالي رحمه الله تعالى من التفاريع البعيدة في علم الكلام،\rفقال في \"الإحياء\" (210/ 1): (فأما الخلاف المحض، ومجادلة الكلام، ومعرفة التفريعات الغريبة .. فلا يزيد التجرد لها مع الإعراض عن غيرها إلا قوة في القلب، وغفلة عن الله تعالى، وتمادياً في الضلال، وطلبا للجاه، إلا من تدارکه الله تعالى برحمته، أو مزج غيره من العلوم الدينية)\r(3) وهو الكتاب الثاني منها، ومما ذكره في هذا الفصل المانع في ترتيب درجات الاعتقاد (343/ 1): (وينبغي أن يحرس سمعه من الجدل والكلام غاية الحراسة؛ فإن ما يشوشه الجدل ="], [118, "وأما مناظراتهم: إن كان القصد منها التعاون على البحث عن مأخذ الشرع ومدارك الأحكام .. فهي سنة السلف، فلقد كانوا يتشاورون ويتناظرون في المسائل الفقهية؛ كما نقل في مسألة الجدِّ (1) , وميراث الأم مع الزوج والأب (2) , ومسائل سواها.\rنعم، إن أبدعوا ألفاظاً وعباراتٍ للتنبيه على مقاصدهم الصحيحة .. فلا حرج فيها، بل هي مباحة لمن يستعيرها ويستعملها (3)، وإن كان مقصدهم المذموم من النظر الإفحامَ دون الإعلام، والإلزامَ دون الاستعلام .. فذلك بدعة على خلاف السنة المأثورة.\r_______________\r= أكثر مما بمهِّده, وما يفسده أكثر مما يصلحه، بل تقويته بالجدل تضاهي ضرب الشجرة بالمِدقَّة من الحديد رجاء تقويتها بأن تكتنز أجزاؤها، وربما يفتِتها ذلك ويفسدها, وهو الأغلب, والمشاهدة تكفيك في هذا بياناً, فناهيك بالعيان برهاناً ... ).\r1) أهو كالأب فيحجب الإخوة، أو أنه ذو حكم خاصّ فيأخذ أحسن أحوال؟\r2) فلم يفرضوا لها الثلث مطلقاً، بل ثلث ما يبقى بعد فرض الزوج.\r3) يعني: وإن كانت من صناعة غير المتديِّنين؛ كالجوهر والعرض اللذين أُنكر استعمالهما في عهد السلف."], [121, "الباب الثالث\rفي فصول متفرقة نافعة في هذا الفن\r"]], "pg": [110, 121]}, "448.18": {"x": [[121, "إن قال قائل: ما الذي دعا رسولَ الله صلى الله عليه وسلم إلى إطلاق هذه الألفاظ الموهِمة مع الاستغناء عنها؟ أكان لا يدري أنه يوهم التشبيه، ويغلط الخلقَ, ويسوقهم إلى اعتقاد الباطل في ذات الله تعالى وصفاته, وحاشا منصب النبوة أن يخفى عليه ذلك؟\rأو عرف لكن لم يبال بجهل الجهال وضلالة الضلال؟ وهذا أبعد وأشنع لأنه بُعث شارحاً لا مبهماً ملبساً ملغِزاً.\rوهذا إشكال له وقع في القلوب؛ حتى جَرَّ بعضَ الخلق إلى سوء الاعتقاد فيه, فقالوا: لو كان نبياً .. لعرف الله تعالى، ولو عرفه .. لما وصفه بما يستحيل عليه في ذاته وصفاته!! (1)\rومالت طائفة أخرى إلى اعتقاد الظواهر؛ وقالوا: لو لم يكن حقاً .. لما ذكره كذلك مطلقاً، ولعدل عنها إلى غيرها أو قرنها بما يزيل الإبهام عنها!! (2)\r___________________\r1) وهذا قول فلاسفة الزنادقة ممّن أظهر الإسلام وأخفى اعتقاده الخبيث. وكذلك الطاعنون في النبوات.\r2) وهو قول عموم المشبهة الإسلاميين؛ كالكرامية ومشبهة الحنابلة."], [122, "فما سبيل حل هذا الإشكال العظيم وقعُهُ في القلوب، الذي تحكيك حسيكتُهُ في الصدور؟ (1)\rالجواب: أن هذا الإشكال منحل عند أهل البصيرة.\rوبيانه: أن هذه الكلمات ما جمعها رسولُ الله صلى الله عليه وسلم دفعةً واحدة، ً وإنما جمعها المائلون الى التشبيه، وقد بينا أن لجمعها من التأثير في الإيهام والتلبيس على الأفهام .. ما ليس لآحادها المفرقة (2)، وإنما هي كلمات لَهِجَ بها في جميع عمره في أوقات متباعدة.\rوإذا اقتُصر منها على ما في القرآن والأخبار المتواترة .. رجعت إلى كلمات يسيرة معدودة، وإن أُضيفت إليها الأخبار الصحيحة .. فهي أيضاً قليلة، وإنما كثرت الروايات الشاذة الضعيفة التي لا يجوز الإلتفات عليها.\rثم ما تواتر منها او صح نقلها عن العدول .. فهي آحادُ كلماتٍ، وما ذكر صلى الله عليه وسلم كلمة منها الاّ مع قرائن وإشاراتٍ ورموزٍ تزيل عنها إيهامُ التشبيه، فإذا نقل الألفاظ مجردة عن تلك القرائن ظهر الإيها.\r_______________\r(1) الحسيكة: العداوة والحقد.\r(2) تقدم (ص 85)"], [123, "وأعظمُ القرائن في زوال الإيهام: المعرفةُ السابقةُ بتقديس الله تعالى عن قبول هذه الظواهر (1)، ومن سبقت معرفتُه\rبذلك .. كانت تلك المعرفةُ ذخيرةً له، راسخةً في نفسه، مقارنةً لكل ما يسمع، فينمحق بها الإيهام انمحاقاً لا يشك فيه،\rويُعرف هذا بأمثلة:\rالأول: أنه صلى الله عليه وسلم سمى الكعبة بيت الله تعالى (2)، وإطلاق هذا يوهم عند الصبيان وعند من تقرب درجتهم منهم ..\rأن الكعبة وطنه ومثواه ومستقره، لكن العوام الذين اعتقدوا أنه في السماء وأن استقراره على العرش .. ينمحق في حقهم هذا الإيهام على وجه لا يشكُّون فيه.\rفلو قيل لهم: ما الذي دعا رسول الله صلى الله عليه وسلم إلى إطلاق هذا اللفظ الموهم المخيل إلى السامع أن الكعبة مسكنه ووطنه؟ لبادروا بأجمعهم وقالوا: هذا إنما يوهم في حق الصبيان والحمقى، وأما من تكرر على سمعه أن الله مستقر على العرش .. فلا يشك عند سماع هذا اللفظ أنه ليس المراد به أن البيت مسكنه ومأواه، بل يعلم على البديهة أن المراد بهذه الإضافة من تشريف, أو معنى سوى ما وضع له لفظ المضاف إلى ربه وساكنه.\r_______________________\r(1) مثل (سورة الإخلاص)، ومثل قوله تعالى: {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11]، وهذه الدلائل النقلية العقلية جمعها الإمام الرازي في «التأسيس» (ص ?? - ??).\r(?) الإضافة هنا بقصد التشريف، ومثله: ناقة الله."], [124, "أليس كان اعتقاده (1) أنه على العرش قرينة أفادته علماً قطعياً بأنه ما أريد بكون الكعبة بيته إنه مأواه؟ وأن هذا إنما يوهم في حق من لم يسبق إلى هذه العقيدة.\rفكذلك رسول الله صلى الله عليه وسلم خاطب به بهذه الألفاظ جماعة سبقوا إلى علم التقديس ونفي التشبيه، وإنه منزه عن الجسمية وعوارضها، وكان ذلك قرينةً قطعيةً مزيلةً للإيهام, لا يبقى معه شك، وإن جاز أن يبقى لبعضهم تردد في تأويله وتعيين المراد به من جملة ما يحتمله اللفظ ويليق بجلال الله تعالى (2).\r*****************\rالمثال ثان: إذا ردد الفقيه في كلامه لفظ (الصورة) بين يدي الصبي أو العامي؛ فقال: صورة هذه المسألة كذا؛ وصورة الواقعة كذا، ولقد صورت المسألة صورة في غاية الحسن .. ربما توهم الصبي أو العامي الذي لا يفهم معنى المسألة أن المسألة شيءٌ له صورة، وفي تلك الصورة أنف وفم وعين؛ على ما عرفه واشتهر عنده من معنى الصورة المعروفة.\rأما من عرف حقيقة المسألة, وإنها عبارة عن علوم مرتبة\r_______________________\r(1) في (ب، ه): (فقد كان اعتقاد هذا العامي).\r(2) قال الإمام الرازي في \"تأسيس النقديس\" (ص 236): (إن العوام يعسر عليهم إثبات موجود ليس بجسم ولا متحيز، فورد القرآن بکلام ظاهره هذا، حتى إذا مال العوام إليه .. رأوه مخلوطة بكلام آخر يفيد التنزيه، فيعتقدونه، والله أعلم)."], [125, "ترتيباً مخصوصاً .. فهل يتصور أن يفهم عيناً وأنفاً وفماً وصورة من جنس الأجسام؟\rهيهات!! بل يكفيه معرفته بأن المسألة منزهة عن الجسمية وعوارضها.\rفكذلك معرفة نفي الجسمية عن حقيقة الإلهية وتقديسها عنها تكون قرينة في قلب كل مستمع مفهمة لمعنى الصورة في قوله: \"خَلَقَ الله آدم على صورته\" (1)، ويتعجب العارف بتقديسه عن الجسمية ممن يتوهم لله تعالى الصورة الجسمانية، كما يتعجب ممن يتوهم للمسألة والواقعة صورة جسمانية!!\r*************\rمثال ثالث: إذا قال القائل بين يدي الصبي: بغداد في يد الخليفة .. ربما ظن وتوهم أن بغداد في أصابع الخليفة، وأنه قد احتوى عليها ببراجمه كما يحتوي على حجرة ومَدَرَةٍ (2)، وكذلك كل عامي لم يفهم المراد بلفظ بغداد.\rأما من علم أن بغداد عبارة عن بلدة كبيرة واسعة الأكناف .. فلا يُتصور أن يَخطُر له ذلك بالبال أو يتوهّمَ, وهل يتصور أن يعترض على قائله ويقول له: لما قلت: (بغداد في يد الخليفة)\r____________________\r(1) تقدم تخريجه (ص 53)، وانظر تفسير (الصورة) في \"تأسيس التقديس\" (ص 121)، وكيف يكون له صورة حقيقية وهو المصور سبحانه؟!\r(2) البراجم: جمع برجمة؛ وهي رؤوس السلاميات من ظهر الكف، أو المفصل الظاهر من مفاصل اليد، والمدرة: قطعة طين يابسة."], [126, "وهذا يفضي إلى الجهل، وبوهم خلاف الحق حتى يعتقد أن بغداد بين أصابعه؟!\rبل لو اعترض بهذا .. لقيل له: يا سليم القلب؛ هذا إنما يوهم الجهل عند من لا يعرف حقيقة بغداد، فأما من يعلمه ..\rفبالضرورة يعلم أنه ما أريد بهذه اليد العضو المشتمل على الكفِّ والأصابع، بل معنىً آخر، ولا يحتاج في فهمه إلى قرينة سوى هذه المعرفة.\rفكذلك جميعُ الألفاظ الموهمة في الأخبار تكفي في دفع إيهامها قرينةٌ واحدةٌ؛ وهي معرفة الله تعالى، و معرفة أنه ليس بجسم, وليس من جنس الأجسام، وهذا مما افتتح رسول الله صلى الله عليه وسلم ببيانه في أول بعثته قبل النطق بهذه الألفاظ.\r****************\rالمثال الرابع: قال رسول الله صلى الله عليه وسلم في نسائه: (أطولُكنُّ يَداً أسرعكن لحاقاً بي) (1)، فكان بعض نسائه تتعرّف الطولَ بالمِساحة ووضع اليد على اليد، حتى ذكر لهن أنه أراد بذلك المساحة في الجود دون الطول للعضو، وكان رسول الله صلى الله عليه وسلم ذكر هذه اللفظة مع قرينة أفهم بها إرادةَ الجود بالتعبير\r_____________________\r(1) رواه مسلم (2452) عن سيدتنا عائشة رضي الله عنها، والمقصودة هي سيدتنا زينب رضي الله عنها؛ لأنها كانت تعمل بيدها وتتصدق كما في تمام الرواية."], [127, "بطول اليد عنه، فلما نقل اللفظ مجرداً عن قرينته .. حصل الإيهام.\rفهل كان لأحد أن يعترض على رسول الله صلى الله عليه وسلم في إطلاقه لفظاً جهل بعضهم معناه؟! إنما ذلك لأنه أطلق إطلاقاً مفهماً في حق الحاضرين مقروناً مثلاً بذكر السخاوة.\rوالناقل قد ينقل اللفظ كما سمعه ولا ينقل القرينة، أو كان بحيث لا يمكن نقلها، أو ظن أنه لا حاجة إلى نقلها، وأن من يسمع يفهمه هو كما فهمه هو لما سمعه، وربما لا يشعر أن فهمه إنما كان بسبب القرينة، فلذلك يقتصر على نقل اللفظ.\rفبمثل هذه الأسباب بقيت الألفاظ مجردة عن قرائنها، فقصرت عن التفهيم، مع أن قرينة معرفة التقديس بمجردها كافيةٌ في نفي الإيهام وإن كانت ربما لا تكفي في تعيين المراد به، فهذه الدقائق لا بد من التنبه لها.\r**************\rمثال خامس: إذا قال قائل بين يدي الصبي ومن يقرب منه درجة ممن لم يمارس الأحوال، ولا عرف العادات في المجالسات: فلان دخل المجمع وجلس فوق فلان .. يوهم السامع الجاهل الغبي أنه جلس على رأسه أو على مكان فوق رأسه!!\rومن عرف العادات وعلم أن ما هو أقرب إلى الصدر اعلى في"], [128, "الرتبة، وأن الفوق عبارة عن العلو يفهم منه أنه جلس بجنبه لا فوق رأسه، لكنه جلس أقرب إلى الصدر.\rفالاعتراض على من خاطب بهذا الكلام وأهل المعرفة بالعادات من حيث إنه يجهل به الصبيان أو الأغبياء .. اعتراضٌ باطل لا أصل له.\rوأمثلة ذلك كثيرة لا تتناهى، ومن لم يقنع باليسير .. لا يزيده الا عياً وجهلاً.\r*\rفقد فهمت على القطع بهذه الأمثلة: أن هذه الألفاظَ الصريحةَ انقلبت مفهوماتُها عن أوضاعها الصريحة بمجرد قرينة، ورجعت تلك القرائن إلى معارفَ سابقة ومقترنة (1)، فكذلك هذه الظواهر الموهمة انقلبت عن الإيهام بسبب تلك القرائن الكثيرة التي بعضها هي المعارف، والواحد منها معرفتهم أنهم لم يؤمروا بعبادة الأصنام، وإن من عبد جسماً .. فقد عبد صنماً؛ سواء كان الجسم صغيراً أو كبيراً، قبيحاً أو جميلاً، سافلاً أو عالياً على الأرض أو على العرش.\rوكان نفي الجسمية ونفي لوازمها معلوماً لكافَّتِهم على الضرورة بإعلام رسول الله صلى الله عليه وسلم والمبالغة في\r__________________\r(1) هذه القرينة تارة تكون عقلية، وتارة تكون لغوية، وهي شئ، وتارة عرفية."], [129, "التنزيه بقوله: {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ} [الشورى: 11]، ولقوله: {وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} [الإخلاص: 4] وقوله سبحانه: {فَلَا تَجْعَلُوا لِلَّهِ أَنْدَادًا وَأَنْتُمْ تَعْلَمُونَ} [البقرة: 22] (1) , وبألفاظ كثيرة لا حصر لها مع قرائن قاطعة لا يمكن حكايتها، وعُلِم ذلك علماً لا ريب فيه.\rوكان ذلك كافياً في تعريفهم استحالة يد هي عضو مركب من لحم وعظم، وكذا في سائر الظواهر بأنها لا تدل إلا على الجسمية وعوارضها لو أطلقت على جسم، ولو أطلق على غير الجسم .. علم ضرورة أنه ما أريد به ظاهره، بل معنى آخر مما يجوز على الله تعالى، ربما يتعين ذلك المعنى، وربما لا يتعين (2)، فهذا مما يزيل الإشكال.\rفإن قيل: فلِم لم يذكر بألفاظ ناصة عليها؛ بحيث لا يوهم ظاهرها جهلاً، ولا في حق الصبي والغبي؟\rقلنا: لأنه إنما كلم الناس بلغة العرب، وليس في لغة العرب ألفاظٌ ناصةٌ على تلك المعاني (3).\r__________________\r(1) وجه الاستدلال بالأوليين ظاهر، وهما آيتان متان، والثالثة مدنية، فالاستدلال بها على ثبوت التنزيه ابتداء بعيد، ولكن على تأكيده، ووجهه كما في «تأسيس التقديس» (ص 71): أن الن المثل، فلو كان تعال? جسمة .. لكان ممثلا للأجسام؛ لأنها كلها متشاركة في الماهية.\r(2) تقدم الحديث على أنه متى يكون ذلك المعنى واجب التعيين أو جائزه (ص 72).\r(3) وهي أثرى اللغات، فكيف بغيرها؟!"], [130, "وكيف يكون في اللغة لها نصوص وواضع اللغة لم يفهم تلك المعاني؟!\rفكيف وضع لها النصوص؟!\rبل هي معان أُدركت بنور النبوة خاصة, أو بنور العقل بعد طول البحث، وذلك أيضاً في بعض تلك الأمور لا في كلها.\rفلما لم يكن لها عبارات موضوعة .. كان استعارة الألفاظ من موضعات اللغة ضرورة كل ناطق بتلك اللغة، كما أنا لا نستغني عن أن نقول: صورة هذه المسألة كذا، وهي تخالف صورة المسألة الأخرى، وهي مستعارة من الصورة الجسمانية، لكن واضع اللغة لما لم يضع لهيئة المسألة وخصوص ترتيبها اسماً نصّاً؛ إما لأنه لم يفهم المسألة وحقيقتها, أو فهمها لكنّه لم يحضره, أو حضره لكنه لم يضع لها لفظاً خاصاً, اعتماداً على إمكان الاستعارة, ولأنه عَلِمَ أنه عاجز عن أن يضع لكل معنى لفظاً خاصاً ناصاً، لأن المعاني غير متناهية العدد، والموضوعات بالضرورة يجب أن تتناهى، فتبقى معان لا نهاية لها يجب أن يستعار اسمها من الموضوع، فاكتُفِىَ بوضع البعض، وسائرُ اللغات أشد قصوراً من لغة العرب.\rفهذا وأمثاله من الضرورة يدعو إلى الاستعارة لمن يتكلم بلغة قوم؛ إذ لا يمكنه أن يخرج عن لغته، كيف ونحن نجوِّز"], [131, "الاستعارة حيث لا ضرورة اعتماداً على القرائن؟! فإنا لا نفرق بين أن يقول القائل: جلس زيد فوق عمرو، وبين أن يقول: جلس أقرب منه إلى الصدر، وأن بغداد في ولاية الخليفة, أو في يده، إذا كان الكلام مع العقلاء، وليس في الإمكان حفظ الألفاظ عن اوهام الصبيان والجهال، فالاشتغال بالاحتراز عن ذلك ركاكة في الكلام، وسخافة في العقل, وثقل في اللفظ.\r\rفإن قيل: فلم لم يكشف الغطاء عن ذات الإله، ولم يقل: إنه موجود ليس بجسم ولا جوهر ولا عرض, ولا هو داخل العالم ولا خارجه (1) ولا متصل ولا منفصل, ولا هو في مكان ولا هو في جهة، بل الجهات كلها خالية عنه؟! فهذا هو الحق عند قوم، والإفصاح عنه كذلك كما أفصح عنه المتكلمون ممكن، ولم يكن في عبارته صلوات الله عليه قصور، ولا في رغبته في كشف الحق فتور، ولا في معرفته نقصان؟\rقلنا: من رأى هذا حقيقة الحق .. اعتذر بأن هذا لو ذكره لنفر الناس عن قبوله، ولبادروا بالإنكار وقالوا: هذا عين المحال، ووقعوا في التعطيل، ولا خير في المبالغة في تنزيه ينتج التعطيل في حق الكافة إلا الأقلين، وقد بعث رسول الله صلى الله عليه وسلم\r____________________\r(1) انظر \"الإحياء\" (265/ 9)، و\"الاقتصاد\" (ص 164)، و\"مشكاة الأنوار\" (ص 89) حول هذه العبارة"], [132, "داعياً للخلق إلى سعادة الآخرة رحمة للعالمين، فكيف ينطق بما فيه هلاك الأكثرين؟! بل أمر أن لا يكلم الناس إلا على قدر عقولهم، وقال صلى الله عليه وسلم: (من حدّث الناس بحديث لا يفهمونه كان فتنةً على بعضهم) (1) أو لفظ هذا معناه.\rفإن قيل: إن كان في المبالغة في التنزيه خوف التعطيل بالإضافة إلى البعض .. ففي استعماله الألفاظ الموهمة خوف التشبيه بالإضافة إلى البعض!!\rقلنا: بينهما فرق من وجهين:\rأحدهما: أن ذلك يدعو إلى التعطيل في حق الأكثرين، وهذا يدعو إلى التشبيه في حق الأقلين.\rوأهون الضررين أولى بالاحتمال، وأعم الضررين أولى بالاجتناب.\rوالثاني: أن علاج وَهْمِ التشبيه أسهل من علاج التعطيل، إذ يكفي أن يقال مع هذه الظواهر: {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11]، وأنه ليس بجسم ولا هو مثل الأجسام.\r_________________\r(1) رواه العقيلي في \"الضعفاء\" (937/ 3) عن سيدنا عبد الله بن عباس رضي الله عنهما، وهو عند الديلمي في \"الفردوس\" (5644) عن سيدتنا عائشة رضي الله عنها، وانظر \"المقاصد الحسنة\" (180)، وفيه الأثر المشهور: \"نحن معاشر الأنبياء أمرنا أن نزل الناس منازلهم، ونكلمهم على قدر عقولهم\"، وروى البخاري (127) عن سيدنا علي رضي الله عنه: (حدثوا الناس بما يعرفون؛ أتحبون أن يكذب الله ورسوله؟!)."], [133, "وأما إثبات موجود في الاعتقاد على ما ذكرناه من المبالغة في التنزيه .. شديداً جداً، بل لا يقبله واحد من الألف؛ لا سيما الأمة الأُميَّةِ العربية.\rفإن قيل: فعجز الناس عن الفهم، هل يمهد عذر الأنبياء في أن يثبتوا في عقائدهم أموراً على خلاف ما هي عليها؛ ليثبت في اعتقادهم أصل الإلهية حتى توهموا - عندهم مثلاً - أن الله مستقر على العرش, وأنه ساكن في السماء, وأنه فوقهم فوقية المكان لا فوقية الرتبة؟\r\rقلنا: معاذ الله أن يظن ذلك أو يتوهم بنبي صادق أن يصف الله تعالى بغير ما هو متصف به، وأن يلقى ذلك في اعتقاد الخلق.\rلا؛ بل تأثيژ قصور الخلق .. في أن يذكر لهم ما يطيقون فهمه، ويكفَّ عنهم ما لا يفهمونه، فلا يعرِّفهم بل يمسك عنهم، وإنما ينطق به مع من يطيقه ويفهمه، ويحصل في ذلك علاج عجز الخلق وقصورهم، ولا ضرورة في تفهيم خلاف الحق قصدا، لا سيما في صفات الله تعالى.\rنعم؛ به ضرورة في استعمال ألفاظ مستعارة ربما يغلظ الأغبياء في فهمها؛ وذلك لقصور اللغات وضرورة المحاورات."], [134, "فأما تفهيم خلاف الحق قصداً إلى التجهيل .. فمحال؛ سواء فُرِضَ فيه مصلحة أو لم يُفرَضْ.\rفإن قيل: قد جهل أهل التشبيه جهلاً يستند إلى ألفاظه, وعلم أن ألفاظه في الظواهر تفضي إلى جهلهم ورضى به، فمهما جاء بلفظ مجهِّل مُلبِّس ورضي به .. لم يفترق الحال بين أن يكون مجرد قصده إلى التجهيل، وبين أن يقصد التجهيل مهما حصل التجهيل، وهو عالم به وراض!!\rقلنا: لا نسلم أن جهل أهل التشبيه حصل بألفاظه، بل بتقصيرهم في كسب معرفة التقديس وتقديمه على النظر في الألفاظ، ولو حصلوا تلك المعرفة التي كلف بها وقدموها على بحث عن الألفاظ .. لما جهلوا، كما أن من حصل علم التقديس .. لم يجهل عند سماعه صورة المسألة كذا.\rبل الواجب عليهم: تحصيل هذا العلم، ثم مراجعة العلماء إذا شكوا في ذلك، ثم كف النفس عن التأويل، وإلزامها التقديس إذا رسم لهم العلماء ذلك، فإذا لم يفعلوا .. جهلوا.\rوعلم الشارع بأن الناس طباعهم الكسل والتقصير والفضول"], [135, "بالخوض فيما ليس من شأنهم .. ليس رِضاً بذلك، ولا سعياً في تحصيل الجهل، لكنه رضا بقضاء الله تعالى في قسمته وتقديره،\rحيث قال: {وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ} [هود: 119]. وقال: {وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً} [هود: 118]. {وَلَوْ شَاءَ رَبُّكَ لَآمَنَ مَن فِي الْأَرْضِ كُلُّهُمْ جَمِيعًا أَفَأَنتَ تُكْرِهُ النَّاسَ حَتَّى يَكُونُوا مُؤْمِنِينَ} [يونس: 99]. {وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ اللَّهِ} [يونس: 100]. {وَلَا يَزَالُونَ مُخْتَلِفِينَ. إِلَّا مَن رَّحِمَ رَبُّكَ وَلِذَلِكَ خَلَقَهُمْ} [هود: 118، 119]. فهذا هو القهر الإلهي في فطرة الخلق, ولا قدرة للأنبياء في تغيير سنته التي لا تبديل لها."], [136, "فصل في التفويض في النصوص المتشابهة\r"]], "pg": [121, 136]}, "448.19": {"x": [[136, "لعلك تقول: الكف عن السؤال والإمساك عن الجواب من أين يغني وقد شاع في البلاد هذه الاختلافات وظهرت التعصبات؟\rفكيف سبيل الجواب إذا سئل عن هذه المسائل؟\rقلنا: الجواب ما قاله مالك رضي الله عنه في مسألة الاستواء إذ قال: الاستواء معلوم، والكيفيّة مجهولة, والإيمان به واجب، والسؤال عنه بدعة (1). فنذكر هذا الجواب في كل مسألة يسأل عنها العوام؛ لينحسم سبيل الفتنة ولا يقتحم العوام ورطة الخطر.\rفإن قيل: فإذا قال قائل: ما قولكم في الإستواء والفوق واليد والأصبع فبماذا نجيب؟\rقلنا: سبيل الجواب أن يقال: الحق فيه ما قاله الرسول صلى الله عليه وسلم, وقاله الله تعالى، ووقد صدق حيث قال: {الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى} [طه: 5]، فنعلم قطعاً أنه ما أراد الجلوس\r_________________\r1) تقدم (ص 59)"], [137, "والاستقرار الذي هو صفة الأجسام، ولا ندري ما الذي أراده, ولم نكلَّف معرفته.\rوقد صدق حيث قال: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ} [الأنعام: 18]، وفوقية المكان محال، فإنه كان قبل المكان فهو الآن على ما عليه كما كان.\rوإذ لم يُرِدْ هذا .. فما الذي أراده؟!\rفلسنا نعرفه، وليس علينا ولا عليك أيها السائل معرفته.\rوكذلك نقول: ولا يجوز إثبات اليد والإصبع مطلقاً، بل يجوز النطق بما نطق به رسول الله صلى الله عليه وسلم على الوجه الذي نطق به من غير زيادة ونقصان، وجمع وتفريق، وتأويل وتفسير كما سبق (1).\rفنقول: صدق حيث قال: (خمَّر طينة آدم بيده) (2)، وحيث قال: (قلب المؤمن بين إِصْبَعَيْنِ من أصابع الرحمن) (3)، فنؤمن بذلك ولا نزيد ولا ننقص، وننقل كما روي، ونقطع بنفي العضو المركب من اللحم والعصب والدم وسائر الأجسام.\rوإذا قيل: القرآن قديم أو مخلوق؟\r____________________\r(1) تقدم (ص 66).\r(2) تقدم تخريجه (ص 51).\r(3) تقدم تخريجه (ص 51)."], [138, "قلنا: هو غير مخلوق؛ لقوله صلى الله عليه وسلم: (القرآن كلام الله غير مخلوق) (1).\rفإن قيل: الحروف قديمة أو لا؟\rقلنا في الجواب: هذه المسألة لم يذكرها الصحابة ولم يخوض فيها, فالخوض فيها بدعة, فلا تسألوا عنها.\rفإن بُلِيَ الإنسان في بلدة غلبت فيها الحشوية وكفروا من لا يقول بقدم الحروف .. فيقول المضطر إلى الجواب: إن عنيت بالحروف نفس القرآن .. فالقرآن قديم، وإن أردت به غير القرآن وصفاته الله تعالى .. فما سوى الله تعالى وصفاته محدث، ولا يزيد عليه؛ لأن تفهيم العوام حقيقةَ هذه المسألة عسيرٌ جداً (2).\rفإن قالوا: فقد قال النبي صلى الله عليه وسلم: (من قرأ حرفاً من القرآن .. فله كذا) (3)، فأثبت الحروف للقرآن، ووصف القرآن بأنه غير مخلوق، فيلزم منه أن الحروف قديمة!!\r___________________\r(1) هو عند الديلمي في «الفردوس» (4118) عن سيدنا أنس رضي الله عنه، وانظر «المقاصد الحسنة» (???).\r(?) لأنها مؤسسة على التفريق بين الكلام النفسي - الذي هو صفة الحق تعال? - وبين لفظ القرآن الذي هو حادث قطعا، وما قاله العضد رحمه الله تعالى بأن حروف القرآن حروف قديمة لا تقبل الترتُّب .. لم يعتمده جمهور أهل السنة.\r(3) كما روى الترمذي (????) من حديث س?دنا عبد الله بن مسعود رضي الله عنه مرفوعة: من قرأ حرفا من كتاب الله .. فله به حسنة."], [139, "قلنا: لا نزيد على ما قاله الرسول صلى الله عليه وسلم؛ وهو أن القرآن غير مخلوق، فهذه مسألة، وأن في القرآن حروفاً, وهذه مسألة ثانية, وأما أن الحروف قديمة .. فهذه مسألة ثالثة ولم ترد, فلا نقول به، ولا نزيد على ما قاله الرسول صلى الله عليه وسلم.\rفإن زعم: أنه يلزمُ من المسألتين السابقتين هذه المسألة الثالثة.\rقلنا: هذا قياس وتفريع، وقد بينا أنه لا سبيل إلى القياس والتفريع (1)، بل يجب الاقتصار على ما ورد من غير تفريع.\rوكذلك إذا قالوا: عربية القرآن قديمة لأنه قال: القرآن قديم، وقال: {أَنزَلْنَاهُ قُرْآنًا عَرَبِيًّا} [يوسف: 2]، فالعربي قديم!!\rفنقول: أما أن القرآن عربي .. فحق؛ إذ نطق به القرآن، وأما أن القرآن قديم .. فحق إذ نطق به الرسول صلى الله عليه وسلم، وأما أن عربية القرآن قديمة .. فهذه مسألة ثالثة لم يرد فيها أنها قديمة، فلا يلزم القول بها.\rفعلى هذا الوجه يُلجِمُ العوامَّ والحشوية عن التصرف فيه، ويزُمُهُم عن القياس والقول باللوازم.\r_____________\r1) لأن القول باللازم فرع عن قياس الغائب على الشاهد, والعمدة أنه ظني عند المحققين الا أن تكون علته عقلية، والظني لا يجوز القول به في ذات الله نعالى وصفاته."], [140, "بل نزيد في التضييق على هذا ونقول: إذا قال: القرآن كلام الله غير مخلوق .. فهذا لا يرخِّص في أن نقول: (القرآن قديم) ما لم يرد لفظ (القديم)، إذ فرق بين غير مخلوق والقديم؛ إذ يقال: كلام فلان غير مخلوق؛ أي غير موضوع، وقد يقال: المخلوق بمعنى المختلق، فلفظ (غير مخلوق) يتطرق إليه هذا, ولا يتطرق إلى لفظ (القديم)، فبينهما فرق، ونحن نعتقد قدم القرآن لا بمجرد هذا اللفظ، فإن هذا اللفظ لا ينبغي أن يحرف ويبدل ويفسَّر ويصرَّف، بل يلزم أن يعتقد أنه حق بالمعنى الذي أراده.\rوكل من وصف الحرف بأنه مخلوق من غير نقل نص فيه مقصود .. فقد أبدع وزاد، ومال عن مذهب السلف وحاد."], [141, "فصل في مراتب الوجود\r"]], "pg": [136, 141]}, "448.20": {"x": [[141, "فإن قيل: من المسائل المعروفة قولهم إن الإيمان قديم، فإذا سئلنا عنه فبم نجيب؟\rقلنا: إن ملكنا زمام الأمر واستولينا على السائل منعناه عن هذا الكلام السخيف الذي لا جدوى له، وقلنا: إن هذا بدعة، وإن كنا مغلوبين في بلادهم فنجيب ونقول: ما الذي أردت بالإيمان؟ إن أردت به شيئاً من معارف الخلق وصفاتهم فجميع صفات الخلق مخلوقة، وإن أردت به شيئاً من القرآن أو من صفات الله تعالى فجميع صفات الله تعالى قديمة، وإن أردت ما ليس صفة للخلق ولا صفة الخالق فهو غير مفهوم ولا متصور وما لا يفهم ولا يتصور ذاته، كيف يفهم حكمه في القدم والحدوث؟ والأصل زجر السائل والسكوت عن الجواب، هذا صفو مقصود مذهب السلف ولا عدول عنه إلا بضرورة، وسبيل المضطر ما ذكرناه."], [142, "فإن وجدنا ذكياً مستعداً لفهم الحقائق .. كشفنا الغطاء عن المسألة, وخلصناه عن الإشكال في القرآن, وقلنا له:\rاعلم أن كل شيء .. فله في الوجود أربع مراتب:\r- وجود في الأعيان،\r- ووجود في الأذهان.\rووجود في اللسان.\rووجود في البياض المكتوب عليه.\rكالنار مثلاً، فإن لها وجوداً في التّنّور.\rولها وجوداً في الخيال والذهن، وأعني بهذا الوجود: العلم بصورة النار وحقيقتها.\rولها وجود في اللسان, وهي الكلمة الدالة عليها؛ أعني لفظ (النار).\rولها وجود في البياض المكتوب عليه بالرقوم.\rوالإحراق صفة خاصة للنار؛ كالقدم للقرآن ولكلام الله تعالى، والمحرق من هذه الجملة: الذي في التنور, دون الذي في الأذهان وفي اللسان وعلى البياض؛ إذ لو كان المحرق هو الذي في البياض أو اللسان .. لاحترق.\rولكن لو قيل لنا: النار محرقة .. قلنا: نعم."], [143, "فإن قيل لنا: كلمة (النار) محرقة .. قلنا: لا.\rفإن قيل: حروف كلمة (النار) محرقة؛ وهي: النون, والألف. والراء .. قلنا: لا.\rفإن قيل: مرقوم هذه الحروف على البياض محرقة .. قلنا: لا.\rفإن قيل: المذكور بكلمة (النار) والمكتوب بكلمة (النار) محرق .. قلنا: نعم؛ لأن المذكور والمكتوب بهذه الكلمة ما في التنور، وما في التنور محرق .. فكذلك القِدَمُ وصف كلام الله تعالى كالإحراق وصف النار.\rوما يطلق عليه اسم القرآن .. وجوده على أربع مراتب:\rأولها: وهي الأصل: وجودُه قائماً بذات الله تعالى يضاهي وجود النار في التنور، {وَلِلَّهِ الْمَثَلُ الْأَعْلَى} [النحل: 60]، ولكن لا بد من هذه الأمثلة في تفهيم العجزة، والقدم وصف خاص لهذا الوجود.\rوالثانية: وجوده العلمي في أذهاننا عند التعلُّم قبل أن ننطق بلساننا.\rثم وجوده في لساننا بتقطيع أصواتنا.\rثم وجوده في الأوراق بالكَتْبةِ."], [144, "فإذا سئلنا عما في أذهاننا من علم القرآن قبل النطق به ..\rقلنا: عِلْمُنا صِفتُنا, وهي مخلوقة, لكن المعلوم به قديم، كما أن علمنا بالنار وثبوت صورتها في خيالنا غير محرق، لكن المعلوم به محرق. وإذا سئلنا عن صوتنا وحركة لساننا ونطقنا .. قلنا: ذلك صفة لساننا، فلساننا حادث, فصوته يوجد بعده، وما هو بعد الحادث حادث بالضرورة، لكن منطوقنا ومذكورنا ومقروءنا ومتلوَّنا بهذه الأصوات الحادثة .. قديم؛ كما إذا ذكرنا حروف النار بلساننا .. كان المذكور بهذه الحروف محرقاً, وأصواتنا وتقطيع أصواتنا غير محرق.\rإلا أن يقول قائل: حروف النار عبارة عن نفس النار!!\rقلنا: إن كان كذلك .. فحروف النار محرقة، وحروف القرآن إن كانت عبارة عن نفس المقروء .. فهي قديمة، وكذلك المخطوط برقوم النار والمكتوب به محرق؛ لأن المكتوب هو نفس النار، أما الرقم الذي هو صورة النار .. غير محرق؛ فإنه في الأوراق من غير إحراق واحتراق.\rفهذه أربع درجات في الوجود تشتبه على العوام, لا يمكنهم إدراك فهم تفاصيلها وخاصية كل واحد منها، فلذلك"], [145, "لا نخوض بهم فيها, لا لجهلنا بحقيقة هذه الأمور وكنه تفاصيلها؛ أن النار من حيث إنها في التنور توصف بأنها محرقة وخامدة ومشتعلة، ومن حيث إنها في اللسان يوصف بأنها عجمي وتركي وعربي, وكثير الحروف وقليله، وما في التنور لا ينقسم إلى العربي والتركي و، وما في اللسان لا توصف بالخمود والاشتعال.\rوإذا كان مكتوباً على البياض .. يوصف بأنه أحمر وأخضر وأسود, وأنه مخطوط بقلم المحقق أو الثلث والرقاع أوالنسخ، وهو في اللسان لا يمكن أن يوصف بذلك.\rواسم النار مطلق على ما في التنور, وما في القلب, وما في اللسان, وما على القرطاس، لكن باشتراك الاسم؛ فأُطلق على ما في التنور حقيقة, وعلى ما في الذهن من العلم لا بالحقيقة, ولكن بمعنى أنها صورة محاكية للنار, كما أن ما يرى في المرآة يسمى إنساناً وناراً لا بالحقيقة، ولكن بمعنى انها صورة محاكية للنار الحقيقي والإنسان، وما في اللسان من الكلمة يسمى باسمه بمعنى ثالث، وهو أنه دلالة دالة على ما في الذهن، وهذا يختلف بالاصطلاحات، والأول والثاني لا اختلاف فيهما، وما في القرطاس يسمى ناراً بمعنى رابع؛ وهو أنها رقوم تدل بالاصطلاح على ما في اللسان.\rومهما فهم اشتراك اسم القرآن والنار وكل شيء من هذه"], [146, "الأمور الأربعة؛ فإذا ورد في الخبر: أن القرآن في قلب العبد, وأنه في المصحف، وانه في لسان القارئ, وأنه في صفة ذات الله تعالى .. صدَّق بالجميع, وفهم معنى بالجميع، ولم تتناقص عنده الأخبار, وصدق بالجميع مع الإحاطة بحقيقة المراد.\rوهذه أمور جلية دقيقة؛ لا أجلى منها عند الفطن الذكي؛ ولا أدق وأغمض منها عند البليد الغبي.\rفحق البليد أن يمنع من الخوض فيه، ويقال له: قل: (القرآن غير مخلوق) واسكت, ولا تزد عليه ولا تنقص, ولا تفتش عنه ولا تبحث.\rوأما الذكي .. فيروَّح عن غمة هذا الإشكال في لحظة (1) ويوصي بألا يحدث العامي به, حتى لا يكلفه ما ليس في طاقته.\rوهكذا جميع مواضع الإشكالات في الظواهر؛ فيها حقائق جلية لأرباب البصائر ملتبسة على العميان من العوام.\rفلا ينبغي أن يظن بأكابر السلف عجزهم عن معرفة هذه الحقيقة وإن لم يحرروا ألفاظها تحرير صنعة, ولكنهم عرفوه وعرفوا عجز العوام, فسكتوا عنهم وأسكتوهم وذلك عين الحق والصواب.\r_________________\r(1) النميمة: الالتباس في الشيء؛ قال تعالى: ولا يكن أمر قيمة."], [147, "لا أعني بأكابر السلف الأكابر من حيث الجاه والاشتهار، ولكن من حيث الغوص على المعاني والاطلاع على الأسرار، وعند هذا ربما انقلب الأمر في حق العوام واعتقدوا في الأشهر أنه الأكبر وذلك سبب آخر من أسباب الضلال."], [148, "فصل في مراتب التصديق الجازم\r"]], "pg": [141, 148]}, "448.21": {"x": [[148, "فإن قال قائل: العامي إذا مُنع من البحث والنظر .. لم يعرف الدليل، ومن لم يعرف الدليل .. كان جاهلاً بالمدلول، وقد أمر الله تعالى كافة عباده بمعرفته، أي بالإيمان به والتصديق بوجوده أولاً، وبتقديسه عن سمات الحوادث ومشابهة غيره ثانياً، وبوحدانيته ثالثاً، وبصفاته من العلم والقدرة ونفوذ المشيئة وغيرها رابعاً.\rوهذه الأمور ليست ضرورية, فهي إذاً مطلوبة، وكل علم مطلوب فلا سبيل إلى اقتناصه وتحصيله إلا بشبكة الأدلة، فلا بد من النظر في الأدلة, والتفطن لوجه دلالتها على المطلوب, وكيفية إنتاجها له، وذلك لا يتم إلا بمعرفة شروط البراهين, وكيفية ترتيب المقدمات واستنتاج النتائج، ويستجر ذلك بالضرورة شيئاً فشيئاً إلى تمام البحث واستيفاء علم الكلام إلى آخر النظر في المعقولات.\rوكذلك يجب على العامي أن يصدق الرسول صلى الله عليه وسلم في كل ما جاء به، وصدقه ليس بضروري, بل هو بشر كسائر الخلق, فلا بد من دليل يميزه عن غيره ممن تحدى بالنبوة كاذباً، ولا يمكن ذلك إلا بالنظر في المعجزته، ومعرفة حقيقة المعجزة وشروطها"], [149, "إلى آخر النظر في النبوات وهو ثلث علم الكلام.\rقلنا: الواجب على الخلق: الإيمان بهذه الأمور.\rوالإيمان: عبارة عن تصديق جازم لا تردد فيه, ولا يشعر صاحبه بإمكان وقوع الخطأ فيه.\rوهذا التصديق الجازم يحصل على ست مراتب:\rالأولى - وهي أقصاها - ما يحصل بالبرهان المستقصى المستوفى شروطه, المحرر أصوله ومقدماته درجة درجة, وكلمة كلمة, حتى لا يبقى مجال احتمال وتمكن التباس، وذلك هو الغاية القصوى.\rربما يتفق ذلك في كل عصر لواحد أو اثنين ممن ينتهي إلى تلك الرتبة، وقد يخلو العصر عنه، ولو كانت النجاة مقصورة على مثل المعرفة لقلَّت النجاة وقل الناجون.\rالثانية: أن يحصل بالأدلة الوهمية الكلامية, المبنية على أمور مسلمة مصدق بها؛ لإشهارها بين أكابر العلماء, وشناعة إنكارها, ونفرة النفوس عن إبداء المراء فيها، وهذا الجنس أيضاً يفيد في بعض الأمور وفي حق بعض الناس تصديقاً جازما؛ ً بحيث لا يشعر صاحبه بإمكان خلافه أصلاً."], [150, "الثالثة: أن يحصل التصديق بالأدلة الخطابية، أعني: التي جرت العادة باستعمالها في المحاورات والمخاطبات الجارية في العادات، وذلك يفيد في حق الأكثرين تصديقاً ببادئ الرأي وسابق الفهم إذا لم يكن الناظر (1) مشحوناً بالتعصب وبرسوخ اعتقاد على خلاف مقتضى الدليل، ولم يكن المشنع مشغوفاً بتكلُّف المماراة والتشكيك, ومتبجحاً بجدل المجادلين في العقائد، وأكثر أدلة القرآن من هذا الجنس.\rفمن الدليل الظاهر المفيد للتصديق: قولنا: لا ينتظم تدبير المنزل بمدبرين، و (لو كان فيهما آلهة إلا الله لفسدتا) (2)، فكل قلب بَاقٍ على الفطرة غير مشوش بمماراة المجادلين .. يسبق من هذا الدليل إلى فهمه تصديق جازم بوحدانية الخالق.\rلكن لو شوشه مجادل وقال: لا يبعد أن يكون العالم بين إلهين يتوافقان ويتعاونان على التدبير ولا يختلفان! فإسماعه هذا القدر يشوش عليه تصديقه، ثم ربما يعسر حلُّ هذا السؤال ودفعه في حق بعض الأفهام القاصرة, فيستولي الشك ويتعذر الدفع.\rوكذلك من الجلي: أن من قدر على الخلق .. فهو على الإعادة أقدر، كما قال تعالى: {قُلْ يُحْيِيهَا الَّذِي أَنْشَأَهَا أَوَّلَ مَرَّةٍ} [يس: 79]. فهذا\r_______________________\r(1) في (أ، ج، و): (الباطن) بدل (الناظر)\r(2) انظر حاشية الباجوري على الجوهرة، (ص 115)."], [151, "لا يسمعه أحد من العوام ذكي أو غبي إلا ويبادر إلى التصديق به، ويقول: نعم؛ ليست الإعادة بأبدع من الابتداء, بل أهون.\rويمكن أن يشوش عليه بسؤال ربما يعسر عليه فهم جوابه، والدليل المستوفى هو الذي يفيد التصديق بعد تمام الأسولة وجوابها بحيث لا يبقى للسؤال مجال, والتصديق يحصل قبل ذلك (1).\rالرابعة: التصديق لمجرد السماع ممن حسن الاعتقاد فيه بسبب كثرة ثناء الخلق عليه، فإن من حسن اعتقاده في أبيه وأستاذه أو في رجل من الأفاضل المشهورين .. قد يخبره عن شيء, كموت شخص, أو قدوم غائب وغيره، فيسبق إليه اعتقاد جازم وتصديق بما اخبر عنه؛ بحيث لا يبقى لغيره مجال في قلبه، ومستنده حسن اعتقاده فيه.\rفالمجرب بالصدق والورع والتقوى مثل الصّدّيق رضي الله عنه إذ قال: قال رسول الله صلى الله عليه وسلم كذا .. فكم من مصدق به جزماً, وقابل له قبولاً مطلقاً, لا مستند لقبوله إلا حسن اعتقاده فيه، فمثله إذا لقى العامي اعتقاداً وقال له: اعلم أن خالق العالم واحد, وأنه عالم قادر, وأنه بعث محمداً صلى الله عليه وسلم\r_________________\r(1) قال العلامة العطار في \"حاشيته على المحلي على جمع الجوامع\" (448/ 2): (القرآن يحتوي على الأدلة الإقناعية والقطعية بحسب أحوال المخاطبين)."], [152, "رسولاً .. بادر إلى التصديق, ولم يمازجه ريب ولا شك في قوله، وكذلك اعتقاد الصبيان في آبائهم ومعلميهم, فلا جرم يسمعون الاعتقادات ويصدقونها, ويستمرُّون عليها من غير حاجة إلى دليل وحجة.\rالرتبة الخامسة: التصديق الذي يسبق إليه العلم عند سماع الشيء مع قرائن أحوال لا تفيد القطع عند المحقق، ولكن تلقى في قلب العوام اعتقاداً جازماً، كما إذا سمع بالتواتر مرض رئيس البلد, ثم ارتفع صراخ وعويل من داره، ثم يسمع من أحد غلمانه أنه قد مات .. اعتقد العامي جزماً أنه مات, ويبنى عليه تدبيره.\rولا يخطر بباله أن الغلام ربما قال ذلك عن إرجاف سمعه، وأن الصراخ والعويل لعله عن غشية أو شدة مرض أو سبب آخر، لكن هذه خواطر بعيدة لا تخطر للعوام, فينطبع في قلوبهم الاعتقادات الجازمة.\rوكم من أعرابي نظر إلى أسارير وجه رسول الله صلى الله عليه وسلم, وإلى حسن كلامه, ولطف شمائله وأخلاقه, فآمن به وصدقه تصديقاً جازماً, لم يخالجه ريب, من غير أن يعالجه بمعجزة يقيمها ويذكر وجه دلالتها (1).\r______________\r(1) ومن لطبف ذلك: ما وقع للصحابي الجليل عبد الله بن سلام رضي الله عنه؛ فقد روى ="], [153, "الرتبة السادسة: أن يسمع القول فيناسب طبعه وأخلاقه، فيبادر إلى التصديق لمجرد موافقته لطبعه, لا من حسن اعتقاده في قائله، ولا من قرينة تشهد له، لكن لمناسبة ما في طباعه.\rفالحريص على موت عدوه وقتله وعزله .. يصدق بجميع ذلك بأدنى إرجاف, ويستمر على اعتقاده جازماً، ولو أخبر بذلك في حق صديقِهِ أو بشيء يخالف شهوته وهواه .. توقَّف فيه وأباه كل الإباء.\rوهذه أضعف التصديقات وأدنى الدرجات؛ لأن ما قبله استند إلى دليل ما وإن كان ضعيفاً؛ من قرينة, أو حسن اعتقاد في المخبر, أو نوع من ذلك, وهي أمارات يظنها العامي أدلة, فتعمل في حقه عمل الأدلة.\rفإذا عرفت مراتب التصديق .. فاعلم أن مستند إيمان العوام هذه الأسباب, وأعلى الدرجات في حقه أدلة القرآن وما يجري مجراه مما يحرك القلب إلى التصديق.\rولا ينبغي أن يُجَاوَزَ بالعامي إلى ما وراء أدلة القرآن وما في معناه من الجليات المقنعة المسكنة للقلوب المستجرة\r________________\r= = الترمذي (2485) من حديثه أنه قال: (فلما استبن وجه رسول الله صلى الله عليه وسلم .. عرف أن وجهه ليس بوجه كذاب)."], [154, "لها إلى الطمأنينة والتصديق؛ فما وراء ذلك ليس على قدر طاقته.\rوأكثر الناس آمنوا في الصبا وكان سبب تصديقهم: مجرد التقليد للآباء والمعلمين؛ لحسن ظنهم بهم، وكثرة ثنائهم على أنفسهم، وثناء غيرهم عليهم، وتشديدهم النكير بين أيديهم على مخالفيهم، وحكايات أنواع النكال النازل بمن لا يعتقد اعتقادهم، وقولهم: إن فلاناً اليهودي في قبره مسخ كلباً، وفلاناً الرافضي انقلب خنزيراً (1)، وحكايات ومنامات وأحوال هذا الجنس ينغرس بها في نفوس الصبيان النفرة عنه والميل إلى ضده؛ حتى يُنزع الشَّكُّ بالكلية عن قلبه.\rفالتعلم في الصغر كالنقش في الحجر، ثم يقع نشوءُه عليه، ولا يزال يؤكد ذلك في نفسه، فإذا بلغ .. استمر على اعتقاده الجازم تصديقه المحكم الذي لا يخالجه فيه ريب.\rولذلك ترى أولاد النصارى والروافض والمجوس والمسلمين كلهم لا يبلغون إلا على عقائد آبائهم، واعتقاداتهم في الباطل والحق جازمة، لو قطعوا إرباً إرباً .. لما كاعوا عنها (2)، وقط لم يسمعوا عليه دليلاً لا حقيقياً ولا رسمياً.\rوكذا ترى العبيد والإماء يُسْبَوْنَ من المعترك ولا يعرفون\r___________________\r(1) في (ب، ه): (النصراني) بدل (الرافضي).\r(2) ما كاع عنها: ما حاد عنها ولا ترکها."], [155, "الإسلام، فإذا وقعوا في أسر المسلمين وصحبوهم مدة ورأوا ميلهم إلى الإسلام .. مالوا معهم واعتقدوا اعتقادهم وتخلقوا بأخلاقهم؛ وكل ذلك لمجرد التقليد والتشبيه بالغير، والطباعُ مجبولة على التشبه لا سيما طباع الصبيان والشباب.\rفبهذا يُعرف أن التصديقَ الجازمَ غيرُ موقوف على البحث وتحرير الأدلة."], [156, "فصل: حصول التصديق من الخلق .. سعادة لهم ولو من غير دليل\r"]], "pg": [148, 156]}, "448.22": {"x": [[156, "لعلك تقول: لا أنكر حصول التصديق الجازم في قلوب العوام بهذه الأسباب، ولكن ليس من المعرفة في شيء، وقد كُلِّفَ الناسُ المعرفةَ الحقيقيةَ دون اعتقاد هو من جنس الجهل؛ لا يميز فيه الباطل عن الحق.\rفالجواب: أن هذا غلط ممن ذهب إليه، بل سعادة الخلق في أن يعتقدوا الشيء على ما هو عليه اعتقاداً جازماً؛ لتنتقش قلوبهم بالصورة الموافقة لحقيقة الحق، حتى إذا ماتوا وانكشف لهم الغطاء فشاهدوا الأمور على ما اعتقدوها .. لم يفتضحوا ولم يحترقوا بنار الخزي والخجلة أولا, ولا بنار جهنم ثانياً.\rوصورة الحق إذا انتقش به قلبه .. فلا نظر إلى السبب المفيد له؛ أهوَ دليل حقيقي، أو رسمي, أو إقناعي، أو قبول من حسن الاعتقاد في قائله, أو قبول بمجرد التقليد من غير سبب، فليس المطلوب الدليل المفيد، بل الفائدة, وهي حقيقية الحق على ما هي عليه.\rفمن اعتقد حقيقة الحق في الله وفي صفاته وكتبه ورسله واليوم الآخر على ما هو عليه فهو سعيد، وإن لم يكن ذلك"], [157, "بدليل محرر كلامي، ولم يكلف الله عباده إلا ذلك.\rوذلك معلوم على الضرورة بجملة أخبار متواترة من رسول الله صلى الله عليه وسلم في موارد الأعراب عليه، وعرضه الإيمان عليهم وقبولهم ذلك, وانصرافهم إلى رعاية الإبل والمواشي من غير تكليفه إياهم التفكر في المعجزة ووجه دلالتها، والتفكر في حدوث العالم وإثبات الصانع، وفي إدلة الوحدانية وسائر الصفات.\rبل الأكثر من أجلاف العرب لو كلفوا ذلك .. لم يفهموه ولم يدركوه بعد طول المدة، بل كان الواحد منه يحلّفه ويقول: بالله؛ آلله أرسلك رسولاً؟ فيقول: والله؛ الله أرسلني رسولاً، وكان يصدقه بيمينه وينصرف (1).\rويقول الآخر إذا قدم عليه ونظر إليه: (والله ما هذا وجه كذاب) (2)، وأمثال ذلك مما لا يحصى.\rبل كل يُسْلِمُ في غزوة واحدة في عصره وعصر أصحابه آلاف لا يفهم الأكثرون منهم أدلة الكلام، ومن كان يفهمه .. يحتاج إلى أن يترك صناعته ويختلف إلى معلم مدة مديدة, ولم ينقل قط شيء من ذلك.\r_______________\r(1) رواه البخاري (??)، ومسلم (??) عن سيدنا أنس رضي الله عنه، وصبغة القسم: (فبالذي خلق السماء وخلق الأرض ونصب الجبال؛ آلله أرسلك؟)\r(?) وهو س?دنا عبد الله بن سلام رضي الله عنه، وتقدم خبره تعليقا (ص ??? - ???)."], [158, "فعلم علماً ضرورياً أن الله تعالى لم يكلف الخلق إلا الإيمان والتصديق الجازم بما قاله كيفما حصل التصديق.\rنعم، لا ينكر أن للعارف درجة على المقلد، ولكن المقلد في الحق مؤمن كما أن العارف مؤمن.\rفإن قلت: فبم يميِّز المقلدُ بين نفسه وبين اليهود والمقلد؟\rقلنا: المقلد لا يعرف التقليد, ولا يعرف أنه مقلد، بل يعتقد في نفسه أنه محقق عارف, ولا يشك في معتقده، ولا يحتاج مع نفسه إلى التمييز؛ لقطعه بأن خصمه مبطل وهو محق، ولعله أيضاً مستظهر بقرائن وأدلة ظاهرة - وإن كانت غير قوية - يرى نفسه مخصوصاً بها ومميزاً بسببها عن خصومه.\rفإن كان اليهودي يعتقد في نفسه مثل ذلك .. فلا يشوش ذلك على المحق اعتقاده، كما أن العارف الناظر ايضاً يزعم أنه يميز نفسه عن اليهودي بالدليل، واليهودي المتكلم الناظر أيضاً يزعم أنه مميز عنه بالدليل، ودعواه ذلك لا يشكك الناظر العارف .. وكذلك لا يشكك المقلد القاطع، ويكفيه في الإيمان أن لا يشككه في اعتقاده معارضة المبطل كلامه بكلامه.\rفهل رأيت عامياً قط قد اغتم وحزن من حيث يعسر عليه الفرق بين تقليده وتقليد اليهودي؟!"], [159, "بل لا يخطر ذلك ببال العوام، وإن أخطر ببالهم وشوفِهوا به .. ضحكوا من قائله وقالوا: ما هذا الهذيان؟! أوكان به بين الحق والباطل مساواة حتى يُحتاج إلى فارق يفرق تبييناً أنه على الباطل، وإني على الحق، وأنا متيقن لذلك غير شاك فيه؟!\rفكيف أطلب الفرق حيث يكون الفرق معلوماً قطعاً من غير طلب؟! فهذه حالة المقلدين الموقنين.\rوهذا إشكال لا يقع لليهودي المبطل لقطعه مذهبَهُ مع نفسه، فكيف يقع للمقلد المسلم الذي وافق اعتقاده ما هو\rالحق عند الله تعالى؟!\rفظهر بهذا على القطع انَّ اعتقادهم جازمة, وأن الشرع لم يكلفهم إلا ذلك.\rفإن قيل: فإن فرضنا عامياً مجادلاً لجوجاً؛ ليس يقلد وليس يقنعه أدلة القرآن ولا الأقاويل الجليلة المقنعة السابقة إلى الأفهام .. فماذا تصنع به؟\rقلنا: هذا مريض مال طبعه عن صحة الفطرة وسلامة الخلقة الأصلية، فيُنظر في شمائله، فإن وجدنا اللجاج والجدل غالباً على طبعه .. لم نجادله، وطهرنا وجه الأرض عنه إن كان يجاحدنا في أصل من أصول الإيمان."], [160, "وإن تفرسنا فيه بالفراسة مخايل الرشد والقبول لوجاوزنا به من الكلام الظاهر إلى تدقيق في الأدلة .. عاجلناه بما قّدرنا عليه من ذلك، وداويناه بالجدال المر والبرهان الحلو (1).\rوبالجملة: فنجتهد أن نجادله بالأحسن كما أمر الله تعالى به, ورخصتنا في هذا القدر من المداواة لا تدل على فتح باب الكلام مع الكافَّةِ، فإنَّ الأدوية تستعمل في حق المرضى وهم الأقلون، وما يعالج به المريض بحكم الضرورة يجب أن يُوقىَ عنه الصحيح.\rوالفطرة الصحيحة الأصلية تُعَدُّ لقبول الإيمان دون المجادلة وتحرير حقائق الأدلة، وليس الضرر في استعمال الدواء مع الأصحاء بأقل من الضرر في إهمال المداواة مع المرضى.\rفليوضع كل شيء موضعه؛ كما أمر الله تعالى به نبيه صلى الله عليه وسلم حيث قال: {ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُم بِالَّتِي هِيَ أَحْسَنُ} [النحل: 125]. والمدعو بالحكمة إلى الحق قوم، وبالموعظة الحسنة قوم آخر، وبالمجادلة بالاحسن قوم آخر, على ما فصَّلنا أقسامهم في كتاب القسطاس المستقيم فلا نطول بإعادته.\r___________________\r(?) مخابل: جمع مخيلة؛ وهي المئة."], [161, "وقد نجز كتاب \"إلجام العوام عن علم الكلام\" وهو آخر تصانيف الإمام المطلق حجَّةِ الإسلام الغزالي رحمه الله.\r****************"]], "pg": [156, 161]}}, "units": {"1": {"tit": "إلجام العوام عن علم الكلام أبو حامد الغزالي", "lvl": 1, "pg": [45, 49]}, "3": {"tit": "الباب الأول: في شرح اعتقاد السلف في هذه الأخبار.", "lvl": 1, "pg": [49, 51]}, "5": {"tit": "الوظيفة الأولى: التقديس", "lvl": 1, "pg": [51, 57]}, "11": {"tit": "الوظيفة الثانية: الإيمان والتصديق", "lvl": 1, "pg": [57, 61]}, "15": {"tit": "الوظيفة الثالثة: الاعتراف بالعجز", "lvl": 1, "pg": [61, 63]}, "17": {"tit": "الوظيفة الرابعة: السكوت عن السؤال", "lvl": 1, "pg": [63, 66]}, "20": {"tit": "الوظيفة الخامسة: الإمساك عن التصرف في ألفاظ واردة", "lvl": 1, "pg": [66, 69]}, "23": {"tit": "أما التصرف الثاني: التأويل،", "lvl": 1, "pg": [69, 83]}, "38": {"tit": "التصريف الثالث الذي يجب الإمساك عنه: التصريف.", "lvl": 1, "pg": [83, 84]}, "39": {"tit": "التصرف الرابع الذي يجب الإمساك عنه: القياس والتفريع،", "lvl": 1, "pg": [84, 85]}, "40": {"tit": "التصرف الخامس: يجمع بين متفرقات.", "lvl": 1, "pg": [85, 86]}, "41": {"tit": "التصرف السادس: التفريق بين المجتمعات", "lvl": 1, "pg": [86, 88]}, "43": {"tit": "الوظيفة السادسة: في الكف بعد الإمساك", "lvl": 1, "pg": [88, 105]}, "57": {"tit": "الباب الثاني في إقامة البرهان على أن الحق مذهب السلف", "lvl": 1, "pg": [105, 110]}, "62": {"tit": "النمط الثاني: البرهان السمعي على ذلك", "lvl": 1, "pg": [110, 121]}, "71": {"tit": "الباب الثالث في فصول متفرقة نافعة في هذا الفن", "lvl": 1, "pg": [121, 136]}, "86": {"tit": "فصل في التفويض في النصوص المتشابهة", "lvl": 1, "pg": [136, 141]}, "91": {"tit": "فصل في مراتب الوجود", "lvl": 1, "pg": [141, 148]}, "98": {"tit": "فصل في مراتب التصديق الجازم", "lvl": 1, "pg": [148, 156]}, "106": {"tit": "فصل: حصول التصديق من الخلق .. سعادة لهم ولو من غير دليل", "lvl": 1, "pg": [156, 161]}}};
